function formatBytes(value){if(value<1024)return `${value} B`;if(value<1024*1024)return `${(value/1024).toFixed(1)} KB`;if(value<1024*1024*1024)return `${(value/1024/1024).toFixed(1)} MB`;return `${(value/1024/1024/1024).toFixed(2)} GB`}
function chooseImageFiles(event){
  const allowed=/\.(heic|heif|jpe?g|png|webp|tiff?|bmp)$/i
  const selected=[...event.target.files],valid=selected.filter(file=>allowed.test(file.name))
  imageFiles.value=valid
  if(valid.length!==selected.length)notify(`已忽略 ${selected.length-valid.length} 个不支持的文件。`,'info')
}
