  if(crawlerInterval.value===-1&&!crawlerCron.value.trim())return notify('请填写 Cron 表达式或使用 AI 转换。','info')
  const urls=crawlerUrls.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)
  if(['twitter','tiktok','douyin','telegram','youtube'].includes(crawlerSource.value)&&!crawlerKeyword.value.trim()){
    const message=crawlerSource.value==='telegram'?(crawlerTelegramMode.value==='search'?'请输入全平台搜索关键词':'请输入 Telegram 频道或群组'):crawlerSource.value==='twitter'&&crawlerTwitterMode.value!=='keyword'?'请输入 X 账号':['tiktok','douyin'].includes(crawlerSource.value)?(crawlerTiktokMode.value==='comments'?`请输入${crawlerShortVideoLabel.value}视频链接`:crawlerTiktokMode.value==='keyword'?`请输入${crawlerShortVideoLabel.value}搜索关键词`:`请输入${crawlerShortVideoLabel.value}账号`):'请输入搜索关键词'
    return alert(message)
  }
  if(crawlerSource.value==='telegram'&&['members','search'].includes(crawlerTelegramMode.value)&&!crawlerCapabilities.value.telegram_api_configured&&(!crawlerTelegram.api_id||!crawlerTelegram.api_hash||!crawlerTelegram.session))return notify('群组成员和全平台搜索需要填写 Telegram 官方 API 授权信息。','info')
  if(crawlerSource.value==='wechat'&&!crawlerAccountName.value.trim()&&!urls.length)return alert('请输入公众号名称或微信文章链接')
  if(!['wechat','twitter','tiktok','telegram','youtube'].includes(crawlerSource.value)&&!urls.length)return alert(crawlerSource.value==='news'?'请输入新闻列表页地址':'请输入至少一个公开网页地址')
  if(!Number.isInteger(Number(crawlerMaxItems.value))||Number(crawlerMaxItems.value)!==-1&&(Number(crawlerMaxItems.value)<1||Number(crawlerMaxItems.value)>500))return notify('最多采集请输入 -1 或 1～500 之间的整数。','info')
  const fields=crawlerFields.value.filter(field=>field.enabled!==false);if(!fields.length)return alert('请至少选择一个采集内容')
  crawlerSubmitting.value=true
  try{
    await axios.post('/api/crawler/tasks',{urls,keyword:crawlerKeyword.value.trim(),account_name:crawlerAccountName.value.trim(),source:crawlerSource.value,twitter_mode:crawlerTwitterMode.value,tiktok_mode:crawlerTiktokMode.value,telegram_mode:crawlerTelegramMode.value,telegram_api_id:crawlerTelegram.api_id,telegram_api_hash:crawlerTelegram.api_hash,telegram_session:crawlerTelegram.session,fields,proxies:crawlerProxies.value.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean),output_format:crawlerOutputFormat.value,interval_minutes:Math.max(0,Number(crawlerInterval.value)||0),cron:crawlerInterval.value===-1?crawlerCron.value.trim():'',delay_seconds:Number(crawlerDelay.value)||1,dynamic:crawlerDynamic.value,max_items:Number(crawlerMaxItems.value),sql_sink:{...crawlerSql,enabled:crawlerOutputFormat.value==='postgresql'},youtube_quality:Number(crawlerYoutubeQuality.value)||720,download_videos:crawlerDownloadVideos.value,article_link_selector:crawlerArticleSelector.value,next_page_selector:crawlerNextPageSelector.value})
    crawlerUrls.value='';crawlerKeyword.value='';crawlerAccountName.value=''
    const message=crawlerSource.value==='news'?'新闻采集任务已创建，正在从列表页查找文章。':crawlerSource.value==='youtube'?'YouTube 视频下载任务已创建，完成后将生成 ZIP。':['tiktok','douyin'].includes(crawlerSource.value)?`${crawlerTiktokActionLabel.value}任务已创建，完成后将生成 ZIP。`:crawlerSource.value==='twitter'?`${crawlerTwitterMode.value==='user'?'X 用户信息':crawlerTwitterMode.value==='history'?'X 历史推文':'X 关键词推文'}采集任务已创建。`:crawlerSource.value==='telegram'?`${crawlerTelegramActionLabel.value}任务已创建。`:crawlerSource.value==='wechat'?'公众号采集任务已创建。':'智能采集任务已创建。'
    crawlerTaskTab.value=(crawlerInterval.value===-1||Number(crawlerInterval.value)>0)?'scheduled':'single'
    notify(message,'success');await loadCrawlerTasks()
  }catch(e){alert(e)}finally{crawlerSubmitting.value=false}
}
