function togglePropzoneArea(area,event){const enabled=event.target.checked;area.visible=enabled;area.download=enabled;area.selected_zone_ids=enabled?(area.zones||[]).map(item=>String(item.properties?.zone_id||'')):[];propzoneAreaLayers.filter(layer=>layer._propzoneId===area.id&&layer._propzoneBoundaryLayer).forEach(layer=>{if(enabled)layer.addTo(propzoneMap);else propzoneMap?.removeLayer(layer)});renderPropzoneZones(area)}
function togglePropzoneZone(area,zone){if(area.visible===false){area.visible=true;area.download=true;propzoneAreaLayers.filter(layer=>layer._propzoneId===area.id&&layer._propzoneBoundaryLayer).forEach(layer=>layer.addTo(propzoneMap))}const id=String(zone.properties?.zone_id||'');const initial=area.selected_zone_ids==null?(area.zones||[]).map(item=>String(item.properties?.zone_id||'')):area.selected_zone_ids;const ids=new Set(initial.map(String));ids.has(id)?ids.delete(id):ids.add(id);area.selected_zone_ids=[...ids];renderPropzoneZones(area)}
async function submitPropzone(){const areas=propzoneSelected.value.filter(area=>area.download!==false).map(({zones,visible,download,...rest})=>rest);if(!areas.length)return alert('请至少勾选一个下载区域');propzoneSubmitting.value=true;try{await axios.post('/api/propzone/tasks',{areas,level:propzoneLevel.value});notify('全美行政区 SHP 下载任务已创建。','success');clearPropzone();propzoneQuery.value='';await loadPropzoneTasks()}catch(e){alert(e.response?.data?.detail||e.message)}finally{propzoneSubmitting.value=false}}
async function controlPropzone(task,action){if(action==='delete'&&!await ask(`删除“${task.name}”及全部 SHP 文件？`))return;try{if(action==='delete')await axios.delete(`/api/propzone/tasks/${task.id}`);else await axios.post(`/api/propzone/tasks/${task.id}/${action}`);await loadPropzoneTasks()}catch(e){alert(e.response?.data?.detail||e.message)}}
async function selectDatabaseType(type){databaseType.value=type;databaseConnection.port=type==='redis'?6379:5432;databaseConnected.value=false;databaseTables.value=[];databaseSelectedTable.value='';databaseSchema.value=null;databaseRows.value=[];databaseTotal.value=0;databasePage.value=0;databaseClientTab.value='data';databaseAddingRow.value=false;databaseEditingRow.value=-1;databaseObjectQuery.value='';if(type==='sqlite'&&databaseConnection.sqlite_path)await testDatabase(true)}
async function pickSqliteFile(){
  if(!databaseNativePickerUnavailable.value){
    databaseSqliteUploading.value=true
    try{
      const selected=(await axios.post('/api/database/sqlite/select')).data,previous=databaseSqliteFile.value
      databaseSqliteHandle=null;databaseSqliteDirect.value=true;databaseSqliteSyncError.value='';databaseSqliteFile.value=selected;databaseConnection.sqlite_path=selected.path
      if(previous?.id)axios.delete(`/api/database/sqlite/files/${previous.id}`).catch(()=>{})
      notify('SQLite 源文件已打开，所有修改将直接保存。','success');await testDatabase(true);return
    }catch(e){const status=e?.response?.status;if(status===409)return;if(![404,501].includes(status))return alert(e);databaseNativePickerUnavailable.value=true}
    finally{databaseSqliteUploading.value=false}
  }
  if(!window.showOpenFilePicker){databaseSqliteHandle=null;databaseSqliteDirect.value=false;databaseSqliteInput.value?.click();return}
  try{
    const [handle]=await window.showOpenFilePicker({multiple:false,types:[{description:'SQLite 数据库',accept:{'application/vnd.sqlite3':['.db','.sqlite','.sqlite3']}}]})
    const permission=handle.requestPermission?await handle.requestPermission({mode:'readwrite'}):'granted'
    if(permission!=='granted')return notify('需要授予文件写入权限，才能直接修改 SQLite 源文件。')
    databaseSqliteHandle=handle;databaseSqliteDirect.value=true;databaseSqliteSyncError.value='';await uploadSqliteSource(await handle.getFile())
  }catch(e){if(e?.name!=='AbortError')alert(e)}
}
async function uploadSqliteFile(event){databaseSqliteHandle=null;databaseSqliteDirect.value=false;const file=event.target.files[0];if(file)await uploadSqliteSource(file)}
async function uploadSqliteSource(file){
  const previous=databaseSqliteFile.value,data=new FormData();data.append('file',file,file.name);databaseSqliteUploading.value=true
  try{const uploaded=(await axios.post('/api/database/sqlite/upload',data)).data;databaseSqliteFile.value=uploaded;databaseConnection.sqlite_path=uploaded.path;if(previous?.id)axios.delete(`/api/database/sqlite/files/${previous.id}`).catch(()=>{});notify(databaseSqliteDirect.value?'SQLite 源文件已打开，可直接编辑。':'SQLite 文件已打开；当前浏览器不支持自动写回源文件。',databaseSqliteDirect.value?'success':'info');await testDatabase(true)}catch(e){if(!previous){databaseSqliteFile.value=null;databaseConnection.sqlite_path=''}databaseSqliteHandle=null;databaseSqliteDirect.value=false;if(databaseSqliteInput.value)databaseSqliteInput.value.value='';alert(e)}finally{databaseSqliteUploading.value=false}
}
async function syncSqliteSource(){if(databaseType.value!=='sqlite'||!databaseSqliteDirect.value||!databaseSqliteHandle||!databaseSqliteFile.value)return;databaseSqliteSyncing.value=true;databaseSqliteSyncError.value='';try{const response=await axios.get(databaseSqliteFile.value.export_url,{responseType:'arraybuffer'});const writable=await databaseSqliteHandle.createWritable();await writable.write(response.data);await writable.close()}catch(e){databaseSqliteSyncError.value=messageOf(e);throw new Error(`数据已提交，但写回 SQLite 源文件失败：${databaseSqliteSyncError.value}`)}finally{databaseSqliteSyncing.value=false}}
async function clearSqliteFile(){const file=databaseSqliteFile.value;if(!file)return;if(databaseSqliteSyncError.value&&!await ask('最近一次修改未能写回源文件，仍要关闭连接吗？','关闭 SQLite'))return;if(file.id)try{await axios.delete(`/api/database/sqlite/files/${file.id}`)}catch(e){console.error(e)}databaseSqliteHandle=null;databaseSqliteDirect.value=false;databaseSqliteSyncError.value='';databaseSqliteFile.value=null;databaseConnection.sqlite_path='';databaseConnected.value=false;databaseTables.value=[];databaseSelectedTable.value='';databaseSchema.value=null;databaseRows.value=[];databaseTotal.value=0;if(databaseSqliteInput.value)databaseSqliteInput.value.value=''}
async function selectDatabaseObject(name){databaseSelectedTable.value=name;databasePage.value=0;databaseClientTab.value='data';await loadDatabaseTable()}
async function testDatabase(silent=false){databaseTesting.value=true;try{const previous=databaseSelectedTable.value,response=(await axios.post('/api/database/test',{config:databaseConfig.value})).data;databaseTables.value=response.tables||[];const retained=databaseTables.value.some(item=>item.name===previous);databaseSelectedTable.value=retained?previous:(databaseTables.value[0]?.name||'');if(!retained)databasePage.value=0;databaseConnected.value=true;databaseSchema.value=null;databaseRows.value=[];databaseTotal.value=0;if(databaseSelectedTable.value)await loadDatabaseTable();if(silent!==true)notify('数据库连接成功。','success')}catch(e){databaseConnected.value=false;alert(e)}finally{databaseTesting.value=false}}
async function loadDatabaseTable(){if(!databaseSelectedTable.value){databaseSchema.value=null;databaseRows.value=[];databaseTotal.value=0;return}databaseLoading.value=true;databaseAddingRow.value=false;databaseEditingRow.value=-1;try{const [schema,rows]=(await Promise.all([axios.post('/api/database/schema',{config:databaseConfig.value,table:databaseSelectedTable.value}),axios.post('/api/database/rows',{config:databaseConfig.value,table:databaseSelectedTable.value,limit:databasePageSize,offset:databasePage.value*databasePageSize})])).map(response=>response.data);databaseSchema.value=schema;databaseRows.value=rows.rows||[];databaseTotal.value=rows.total??databaseRows.value.length}catch(e){alert(e)}finally{databaseLoading.value=false}}
async function changeDatabasePage(direction){const next=databasePage.value+direction;if(next<0||next>=databasePageCount.value)return;databasePage.value=next;await loadDatabaseTable()}
function databaseCellText(value){if(value===null||value===undefined)return 'NULL';if(typeof value==='object')return JSON.stringify(value);return String(value)}
function databaseTypedValue(value,column){if(value==='')return column?.primary_key?undefined:(column?.nullable?null:'');const type=(column?.type||'').toLowerCase();if(/int|real|float|double|numeric|decimal/.test(type)){const number=Number(value);return Number.isNaN(number)?value:number}if(/bool/.test(type))return value===true||value==='true'||value==='1';return value}
function databaseRowPayload(values){const result={};databaseDisplayColumns.value.forEach(column=>{const value=databaseTypedValue(values[column.name],column);if(value!==undefined)result[column.name]=value});return result}
function startDatabaseAdd(){databaseAddingRow.value=true;databaseEditingRow.value=-1;databaseNewValues.value=Object.fromEntries(databaseDisplayColumns.value.map(column=>[column.name,'']))}
function startDatabaseEdit(row,index){databaseEditingRow.value=index;databaseAddingRow.value=false;databaseOriginalRow.value={...row};databaseEditValues.value={...row}}
function cancelDatabaseEdit(){databaseEditingRow.value=-1;databaseOriginalRow.value=null;databaseEditValues.value={}}
function databaseWhereFor(row){const primary=databaseColumns.value.filter(column=>column.primary_key);const columns=primary.length?primary:databaseColumns.value;return Object.fromEntries(columns.map(column=>[column.name,row[column.name]]))}
async function saveDatabaseNew(){databaseCrudSubmitting.value=true;try{const values=databaseRowPayload(databaseNewValues.value);await axios.post('/api/database/crud',{config:databaseConfig.value,action:'create',table:values.key||databaseSelectedTable.value,values,where:{}});await syncSqliteSource();databaseAddingRow.value=false;notify(databaseSqliteDirect.value?'新记录已写入源文件。':'新记录已添加。','success');await testDatabase(true)}catch(e){alert(e)}finally{databaseCrudSubmitting.value=false}}
async function saveDatabaseEdit(){const row=databaseOriginalRow.value;if(!row)return;databaseCrudSubmitting.value=true;try{await axios.post('/api/database/crud',{config:databaseConfig.value,action:'update',table:databaseSelectedTable.value,values:databaseRowPayload(databaseEditValues.value),where:databaseWhereFor(row)});await syncSqliteSource();cancelDatabaseEdit();notify(databaseSqliteDirect.value?'修改已写入源文件。':'记录已保存。','success');await testDatabase(true)}catch(e){alert(e)}finally{databaseCrudSubmitting.value=false}}
async function deleteDatabaseRow(row){if(!await ask('确定删除当前记录？该操作会直接修改数据库。','删除记录'))return;databaseCrudSubmitting.value=true;try{await axios.post('/api/database/crud',{config:databaseConfig.value,action:'delete',table:databaseSelectedTable.value,values:{},where:databaseWhereFor(row)});await syncSqliteSource();notify(databaseSqliteDirect.value?'记录已从源文件删除。':'记录已删除。','success');await testDatabase(true)}catch(e){alert(e)}finally{databaseCrudSubmitting.value=false}}
async function createDatabaseExport(){if(!databaseConnected.value)return alert('请先测试数据库连接');databaseTaskSubmitting.value=true;try{const tables=databaseExportAll.value?[]:databaseExportTables.value;await axios.post('/api/database/tasks/export',{config:databaseConfig.value,tables});notify('数据库导出任务已创建。','success');await loadDatabaseTasks()}catch(e){alert(e)}finally{databaseTaskSubmitting.value=false}}
function chooseDatabaseImport(event){databaseImportFile.value=event.target.files[0]||null}
async function createDatabaseImport(){if(!databaseImportFile.value)return alert('请选择数据库备份 ZIP 或 JSON 文件');databaseTaskSubmitting.value=true;try{const data=new FormData();data.append('config',JSON.stringify(databaseConfig.value));data.append('archive',databaseImportFile.value,databaseImportFile.value.name);data.append('overwrite',String(databaseOverwrite.value));const task=(await axios.post('/api/database/tasks/import',data)).data;if(databaseType.value==='sqlite'&&databaseSqliteDirect.value)databasePendingSqliteImport.value=task.id;databaseImportFile.value=null;if(databaseImportInput.value)databaseImportInput.value.value='';notify('数据库导入任务已创建。','success');await loadDatabaseTasks()}catch(e){alert(e)}finally{databaseTaskSubmitting.value=false}}
