async function deleteDatabaseTask(task){if(!await ask(`删除“${task.name}”任务及其备份文件？`))return;try{await axios.delete(`/api/database/tasks/${task.id}`);notify('数据库任务及文件已删除。','success');await loadDatabaseTasks()}catch(e){alert(e)}}

function messageOf(value){
  const detail=value?.response?.data?.detail??value?.message??value
  return Array.isArray(detail)?detail.map(item=>item.msg||String(item)).join('\n'):String(detail||'操作失败')
}
function notify(message,type='error',title=''){
  const id=Date.now()+Math.random();toasts.value.push({id,message:messageOf(message),type,title:title||(type==='success'?'操作成功':type==='info'?'提示':'操作失败')})
  setTimeout(()=>{toasts.value=toasts.value.filter(item=>item.id!==id)},type==='error'?7000:3500)
}
const alert=(message)=>notify(message,'error')
function ask(message,title='确认删除'){
  return new Promise(resolve=>Object.assign(confirmDialog,{open:true,title,message,resolve}))
}
function settleConfirm(result){const resolve=confirmDialog.resolve;confirmDialog.open=false;confirmDialog.resolve=null;resolve?.(result)}

function elevationColor(value){
  if(value<0)return [42,91,138]
  const stops=[[0,52,126,72],[300,112,156,82],[800,196,183,92],[1600,166,119,74],[3000,124,104,91],[5000,245,245,240]]
  for(let i=1;i<stops.length;i++)if(value<=stops[i][0]){const a=stops[i-1],b=stops[i],t=(value-a[0])/(b[0]-a[0]);return [1,2,3].map(k=>Math.round(a[k]+(b[k]-a[k])*t))}
  return [255,255,255]
}
function createDemLayer(){
  const Terrain=L.GridLayer.extend({createTile(coords,done){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d');fetch(`https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${coords.z}/${coords.x}/${coords.y}.png`).then(r=>{if(!r.ok)throw Error(r.status);return r.blob()}).then(createImageBitmap).then(bitmap=>{ctx.drawImage(bitmap,0,0);const image=ctx.getImageData(0,0,256,256),p=image.data;for(let i=0;i<p.length;i+=4){const h=p[i]*256+p[i+1]+p[i+2]/256-32768,[r,g,b]=elevationColor(h);p[i]=r;p[i+1]=g;p[i+2]=b;p[i+3]=255}ctx.putImageData(image,0,0);done(null,canvas)}).catch(error=>{ctx.fillStyle='#d8d2bf';ctx.fillRect(0,0,256,256);done(error,canvas)});return canvas}})
  return new Terrain({maxNativeZoom:15,maxZoom:20,attribution:'Elevation © AWS Open Data / Mapzen'})
}
function bingQuadkey(x,y,z){let key='';for(let level=z;level>0;level--){let digit=0,mask=1<<(level-1);if(x&mask)digit++;if(y&mask)digit+=2;key+=digit}return key}
function createSatelliteTileLayer(source){
  if(source.id==='bing_aerial'){
    const BingLayer=L.TileLayer.extend({getTileUrl(coords){return `https://ecn.t${(coords.x+coords.y)%4}.tiles.virtualearth.net/tiles/a${bingQuadkey(coords.x,coords.y,coords.z)}.jpeg?g=1`}})
    return new BingLayer('',{maxZoom:20,maxNativeZoom:source.maxZoom,attribution:source.attribution})
  }
  if(source.id==='amap_hybrid'){
    const common={maxZoom:20,maxNativeZoom:18,attribution:source.attribution}
    const labels=L.tileLayer('https://wprd02.is.autonavi.com/appmaptile?lang=zh_cn&size=1&scl=1&style=8&ltype=7&x={x}&y={y}&z={z}',common)
    return L.layerGroup([L.tileLayer(source.url,common),labels])
  }
  const layer=L.tileLayer(source.url,{maxZoom:20,maxNativeZoom:source.maxZoom,subdomains:source.subdomains||'abc',attribution:source.attribution})
  return layer
}
function switchMapType(){
  form.data_type=mapCategory.value==='dem'?'dem':'satellite'
  const available=availableTileSources.value
  if(!available.some(source=>source.id===form.tile_source))form.tile_source=available[0]?.id||'google_satellite'
  const selectedSource=tileSources.find(source=>source.id===form.tile_source)
  if(selectedSource){form.zoom_min=Math.max(selectedSource.minZoom,Math.min(form.zoom_min,selectedSource.maxZoom));form.zoom_max=Math.max(form.zoom_min,Math.min(form.zoom_max,selectedSource.maxZoom))}
  if(form.data_type==='dem')form.output_format='tif'
  if(!map.value)return
  if(satelliteLayer)map.value.removeLayer(satelliteLayer);if(demLayer)map.value.removeLayer(demLayer)
  if(form.data_type==='dem')demLayer.addTo(map.value)
  else{satelliteLayer=createSatelliteTileLayer(selectedSource);satelliteLayer.addTo(map.value)}
}
watch(()=>[mapCategory.value,form.tile_source],switchMapType)

function go(target){view.value=target;location.hash=target;window.scrollTo({top:0,left:0,behavior:'instant'});if(target==='map')nextTick(()=>map.value?.invalidateSize());if(target==='shp')nextTick(initShpMap);if(target==='propzone')nextTick(initPropzoneMap);if(target==='trending')loadTrendingDates();if(target==='md-word')loadMdWordTasks();if(target==='image-convert')loadImageTasks();if(target==='database')loadDatabaseTasks();if(target==='propzone')loadPropzoneTasks();if(target==='crawler')loadCrawlerFields()}
function syncHash(){view.value=location.hash.slice(1)||'home';window.scrollTo({top:0,left:0,behavior:'instant'});if(view.value==='map')nextTick(()=>map.value?.invalidateSize());if(view.value==='shp')nextTick(initShpMap);if(view.value==='propzone')nextTick(initPropzoneMap);if(view.value==='trending')loadTrendingDates();if(view.value==='md-word')loadMdWordTasks();if(view.value==='image-convert')loadImageTasks();if(view.value==='database')loadDatabaseTasks();if(view.value==='propzone')loadPropzoneTasks();if(view.value==='crawler')loadCrawlerFields()}

async function loadTrendingReport(date){trendingLoading.value=true;try{trendingReport.value=(await axios.get(`/api/github-trending/reports/${date}`)).data}catch(e){alert(e)}finally{trendingLoading.value=false}}
async function loadTrendingFavorites(){try{trendingFavorites.value=(await axios.get('/api/github-trending/favorites')).data}catch(e){alert(e)}}
async function loadTrendingDates(){
  trendingLoading.value=true
  try{await loadTrendingFavorites();trendingDates.value=(await axios.get('/api/github-trending/reports')).data;if(trendingDates.value.length)await loadTrendingReport(trendingDates.value[0].date);else await refreshTrending()}catch(e){alert(e)}finally{trendingLoading.value=false}
}
async function refreshTrending(){trendingRefreshing.value=true;try{trendingReport.value=(await axios.post('/api/github-trending/refresh')).data;trendingDates.value=(await axios.get('/api/github-trending/reports')).data;notify('今日 GitHub 热门报告已更新。','success')}catch(e){alert(e)}finally{trendingRefreshing.value=false}}
async function toggleTrendingFavorite(repo){
  try{
    if(trendingFavoriteNames.value.has(repo.full_name)){const [owner,name]=repo.full_name.split('/');await axios.delete(`/api/github-trending/favorites/${encodeURIComponent(owner)}/${encodeURIComponent(name)}`);notify('已取消收藏。','success')}
    else{await axios.post('/api/github-trending/favorites',{repository:repo,source_date:trendingReport.value?.date||repo.source_date||''});notify('已加入收藏。','success')}
    await loadTrendingFavorites()
  }catch(e){alert(e)}
}

function initShpMap(){
  if(!shpMap&&shpMapEl.value){shpMap=L.map(shpMapEl.value).setView([35,105],4);L.tileLayer('https://mt1.google.com/vt/lyrs=s&x={x}&y={y}&z={z}',{maxZoom:20,attribution:'Satellite imagery © Google'}).addTo(shpMap);loadShpLayers()}
  else shpMap?.invalidateSize()
}
function chooseShpFiles(event){
  const files=[...event.target.files],allowed=new Set(['.shp','.shx','.dbf','.prj','.cpg'])
  shpFiles.value=files.filter(file=>allowed.has(file.name.slice(file.name.lastIndexOf('.')).toLowerCase()))
}
const selectedShpGroupCount=computed(()=>new Set(shpFiles.value.filter(file=>file.name.toLowerCase().endsWith('.shp')).map(file=>file.name.slice(0,-4))).size)
function shpColor(id){let value=0;for(const char of id)value=(value*31+char.charCodeAt(0))>>>0;return `hsl(${value%360} 68% 48%)`}
async function addShpLayer(meta){
  if(!shpMap||shpLayers.value.some(item=>item.id===meta.id))return
  const geojson=(await axios.get(`/api/shp-preview/layers/${meta.id}/geojson`)).data,color=shpColor(meta.id)
  const layer=L.geoJSON(geojson,{style:{color,weight:2,fillColor:color,fillOpacity:.2},pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:5,color,fillColor:color,fillOpacity:.8}),onEachFeature:(f,l)=>{const entries=Object.entries(f.properties||{}).filter(([,v])=>v!==null&&String(v).trim()&&String(v).toUpperCase()!=='NULL').slice(0,6);if(entries.length){const box=document.createElement('div');entries.forEach(([k,v])=>{const row=document.createElement('div');row.textContent=`${k}: ${v}`;box.appendChild(row)});l.bindTooltip(box,{sticky:true,direction:'auto',offset:[12,12],opacity:1,className:'shp-feature-tooltip'})}}}).addTo(shpMap)
  shpLayers.value.push({...meta,visible:true,layer})
}
async function loadShpLayers(){
  try{const list=(await axios.get('/api/shp-preview/layers')).data;const ids=new Set(list.map(x=>x.id));shpLayers.value.filter(x=>!ids.has(x.id)).forEach(x=>x.layer&&shpMap?.removeLayer(x.layer));shpLayers.value=shpLayers.value.filter(x=>ids.has(x.id));for(const meta of list)await addShpLayer(meta)}catch(e){console.error(e)}
}
async function uploadShp(){
  if(!shpFiles.value.length)return alert('请选择一个或多个完整 SHP 文件组')
  const data=new FormData();shpFiles.value.forEach(file=>data.append('files',file,file.webkitRelativePath||file.name));shpUploading.value=true
  try{const created=(await axios.post('/api/shp-preview/layers',data)).data;for(const meta of created)await addShpLayer(meta);shpFiles.value=[];if(shpInput.value)shpInput.value.value='';notify(`已添加 ${created.length} 个 SHP 图层。`,'success');if(created.length)locateShp(shpLayers.value.find(x=>x.id===created[created.length-1].id))}catch(e){alert(e)}finally{shpUploading.value=false}
}
function toggleShp(item){item.visible=!item.visible;if(item.visible)item.layer.addTo(shpMap);else shpMap.removeLayer(item.layer)}
function locateShp(item){if(!item?.layer)return;const bounds=item.layer.getBounds();if(bounds.isValid())shpMap.fitBounds(bounds,{padding:[30,30]})}
async function deleteShp(item){if(!await ask(`删除“${item.name}”图层及上传的 SHP 文件组？`))return;try{await axios.delete(`/api/shp-preview/layers/${item.id}`);if(item.layer)shpMap.removeLayer(item.layer);shpLayers.value=shpLayers.value.filter(x=>x.id!==item.id);notify('SHP 图层已删除。','success')}catch(e){alert(e)}}

function boundsOf(item){const b=item.layer.getBounds();return {west:b.getWest(),south:b.getSouth(),east:b.getEast(),north:b.getNorth()}}
function clearAreas(){layers.value.forEach(x=>map.value.removeLayer(x.layer));layers.value=[]}
function mapLayerId(layer){return layer?L.stamp(layer):null}
function removeAreaByMapLayer(removedLayer){
  const removedId=mapLayerId(removedLayer)
  const matched=layers.value.filter(item=>item.layerId===removedId||mapLayerId(item.layer)===removedId||(typeof item.layer?.hasLayer==='function'&&item.layer.hasLayer(removedLayer)))
  if(!matched.length)return
  layers.value=layers.value.filter(item=>!matched.includes(item))
  matched.forEach(item=>{if(item.layer!==removedLayer&&map.value?.hasLayer(item.layer))map.value.removeLayer(item.layer)})
}
function resetMapDownloadForm(){
  clearAreas();regionQuery.value='';regionResults.value=[]
  map.value?.pm?.disableDraw()
  mapCategory.value='imagery'
  Object.assign(form,{data_type:'satellite',tile_source:'google_satellite',zoom_min:1,zoom_max:17,max_workers:8,split_size:2048,output_format:'png'})
}
async function searchRegions(){
  if(regionQuery.value.trim().length<2) return
  searching.value=true
  try{regionResults.value=(await axios.get('/api/regions/search',{params:{q:regionQuery.value}})).data}
  catch(e){alert(e.response?.data?.detail||e.message)}finally{searching.value=false}
}
function selectRegion(region){
  const layer=L.geoJSON(region.geometry,{style:{color:'#bb5d35',weight:2,fillColor:'#d9855e',fillOpacity:.18}}).addTo(map.value)
  layers.value=[...layers.value,{layer,layerId:mapLayerId(layer),geometry:region.geometry,name:region.name}]
  map.value.fitBounds(layer.getBounds(),{padding:[20,20]}); regionResults.value=[]; regionQuery.value=region.name.split(',')[0]
}
async function submit(){
  if(!layers.value.length) return alert('请先使用地图左侧矩形工具框选范围')
  const source=selectedTileSource.value
  if(!source||form.zoom_min<source.minZoom||form.zoom_max>source.maxZoom||form.zoom_min>form.zoom_max)return alert(`所选数据源仅支持 Z${source?.minZoom??0}–Z${source?.maxZoom??20}，请检查起止层级`)
  submitting.value=true
  try{
    const payload={tasks:layers.value.map(item=>({bounds:boundsOf(item),geometry:item.geometry,options:{...form,output_name:item.name?.split(',')[0]||''}}))}
    await axios.post('/api/tasks/batch',payload);notify('下载任务已加入队列，可在任务列表查看进度。','success');resetMapDownloadForm();await loadTasks()
  }catch(e){alert(e.response?.data?.detail||e.message)}finally{submitting.value=false}
}
async function loadTasks(){try{tasks.value=(await axios.get('/api/tasks')).data}catch(e){console.error(e)}}
async function loadDockerTasks(){try{dockerTasks.value=(await axios.get('/api/docker/tasks')).data}catch(e){console.error(e)}}
async function loadVersions(){versionsLoading.value=true;try{Object.assign(versions,(await axios.get('/api/docker/versions',{params:{arch:dockerForm.arch}})).data)}catch(e){console.error(e)}finally{versionsLoading.value=false}}
async function submitDocker(){if(compatibilityError.value)return alert(compatibilityError.value);dockerSubmitting.value=true;try{await axios.post('/api/docker/tasks',dockerForm);notify('Docker 离线包任务已创建。','success');Object.assign(dockerForm,{arch:'x86_64',docker_version:'',compose_version:''});await Promise.all([loadDockerTasks(),loadVersions()])}catch(e){alert(e)}finally{dockerSubmitting.value=false}}
async function controlDocker(task,action){
  if(action==='delete'&&!await ask(`删除后将同时清理“${task.name}”生成的全部文件，此操作无法撤销。`)) return
  try{if(action==='delete') await axios.delete(`/api/docker/tasks/${task.id}`);else await axios.post(`/api/docker/tasks/${task.id}/${action}`);await loadDockerTasks()}catch(e){alert(e.response?.data?.detail||e.message)}
}
async function loadGjbTasks(){
  try{
    gjbTasks.value=(await axios.get('/api/gjb/tasks')).data
    if(autoPreviewTaskId.value&&!previewLoading.value){
      const current=gjbTasks.value.find(task=>task.id===autoPreviewTaskId.value)
      if(current?.status==='completed')await previewGjb(current)
      else if(current?.status==='failed')autoPreviewTaskId.value=null
    }
  }catch(e){console.error(e)}
}
function chooseGjbFiles(event){gjbFiles.value=[...event.target.files]}
async function submitGjb(){
  if(!gjbFiles.value.length)return alert('请选择 GJB 地图目录')
  const data=new FormData();gjbFiles.value.forEach(file=>data.append('files',file,file.name));data.append('crs',gjbForm.crs)
  gjbSubmitting.value=true;try{const created=(await axios.post('/api/gjb/tasks',data)).data;notify('文件上传完成，转换任务已开始。','success');autoPreviewTaskId.value=created.id;gjbFiles.value=[];gjbForm.crs='auto';if(gjbInput.value)gjbInput.value.value='';await loadGjbTasks()}catch(e){alert(e)}finally{gjbSubmitting.value=false}
}
async function controlGjb(task,action){
  if(action==='delete'&&!await ask(`删除后将同时清理“${task.name}”转换结果及上传文件，此操作无法撤销。`))return
  try{if(action==='delete'){await axios.delete(`/api/gjb/tasks/${task.id}`);if(previewTask.value?.id===task.id){previewTask.value=null;if(gjbMap){gjbMap.remove();gjbMap=null}}if(autoPreviewTaskId.value===task.id)autoPreviewTaskId.value=null}else await axios.post(`/api/gjb/tasks/${task.id}/retry`);await loadGjbTasks()}catch(e){alert(e.response?.data?.detail||e.message)}
}
async function previewGjb(task){
  previewLoading.value=true
  try{
    const geojson=(await axios.get(`/api/gjb/tasks/${task.id}/preview`)).data;previewTask.value=task;await nextTick()
    if(gjbMap){gjbMap.remove();gjbMap=null}
    gjbMap=L.map(gjbMapEl.value).setView([35,105],4);L.tileLayer('https://mt1.google.com/vt/lyrs=s&x={x}&y={y}&z={z}',{maxZoom:20,attribution:'Satellite imagery © Google'}).addTo(gjbMap)
    const groupColors={A:'#ffdf6c',B:'#fb7185',C:'#f97316',D:'#94a3b8',E:'#eab308',F:'#38bdf8',I:'#06b6d4',J:'#c08457',K:'#a78bfa',L:'#4ade80',R:'#f8fafc'}
    const featureColor=f=>groupColors[f?.properties?.group]||'#f06b3d'
    const previewPoint=(feature,latlng)=>{
      const marker=L.circleMarker(latlng,{radius:feature?.properties?.type==='N'?1:4,color:featureColor(feature),fillColor:featureColor(feature),fillOpacity:.75})
      if(feature?.properties?.type==='N'&&feature.properties.name){const label=document.createElement('span');label.textContent=feature.properties.name;marker.bindTooltip(label,{permanent:true,direction:'center',className:'gjb-place-label',opacity:1})}
      return marker
    }
    const typeNames={P:'点要素 · SHP',L:'线要素 · SHP',A:'面要素 · SHP',N:'地名注记 · SHP'}
    const overlays={},visibleLayers=[]
    Object.entries(typeNames).forEach(([type,name])=>{const features=geojson.features.filter(f=>f.properties?.type===type);if(!features.length)return;const item=L.geoJSON({type:'FeatureCollection',features},{style:f=>({color:featureColor(f),weight:f?.properties?.group==='J'?2.2:1.6,fillColor:featureColor(f),fillOpacity:.18}),pointToLayer:previewPoint,onEachFeature:(f,l)=>{const text=String(f?.properties?.name||'').trim();if(text&&text.toUpperCase()!=='NULL'&&f.properties.type!=='N')l.bindTooltip(text)}}).addTo(gjbMap);overlays[name]=item;visibleLayers.push(item)})
    L.control.layers(null,overlays,{collapsed:false,position:'topright'}).addTo(gjbMap)
    const layer=L.featureGroup(visibleLayers)
    if(layer.getBounds().isValid())gjbMap.fitBounds(layer.getBounds(),{padding:[20,20]})
    if(autoPreviewTaskId.value===task.id)autoPreviewTaskId.value=null
  }catch(e){alert(e.response?.data?.detail||e.message);autoPreviewTaskId.value=null}finally{previewLoading.value=false}
}
async function loadEsTasks(){try{esTasks.value=(await axios.get('/api/es/tasks')).data}catch(e){console.error(e)}}
async function connectEs(){esConnecting.value=true;try{const data=(await axios.post('/api/es/connect',esConnection)).data;esInfo.value=data;esIndexes.value=data.indices;selectedIndexes.value=[];notify(`已连接集群 ${data.cluster_name||''}，获取到 ${data.indices.length} 个索引。`,'success')}catch(e){esInfo.value=null;alert(e)}finally{esConnecting.value=false}}
function toggleAllIndexes(){selectedIndexes.value=selectedIndexes.value.length===esIndexes.value.length?[]:esIndexes.value.map(item=>item.index)}
function chooseEsFiles(event){esFiles.value=[...event.target.files]}
async function submitEs(){
  if(esMode.value==='export'&&!selectedIndexes.value.length)return alert('请至少选择一个索引')
  if(esMode.value==='import'&&!esFiles.value.length)return alert('请选择导出 ZIP 或 mapping/data 目录')
  esSubmitting.value=true
  try{
    if(esMode.value==='export')await axios.post('/api/es/tasks/export',{connection:esConnection,indexes:selectedIndexes.value})
    else{const data=new FormData();esFiles.value.forEach(file=>data.append('files',file,file.webkitRelativePath||file.name));Object.entries(esConnection).forEach(([k,v])=>data.append(k,String(v)));data.append('overwrite',String(esOptions.overwrite));await axios.post('/api/es/tasks/import',data);esFiles.value=[];if(esZipInput.value)esZipInput.value.value='';if(esDirInput.value)esDirInput.value.value=''}
    notify(esMode.value==='export'?'ES 导出任务已创建。':'ES 导入任务已创建。','success');selectedIndexes.value=[];await loadEsTasks()
  }catch(e){const detail=e.response?.data?.detail;alert(Array.isArray(detail)?detail.map(x=>x.msg).join('\n'):detail||e.message)}finally{esSubmitting.value=false}
}
async function controlEs(task,action){if(action==='delete'&&!await ask(`删除后将同时清理任务“${task.name}”及其文件，此操作无法撤销。`))return;try{if(action==='delete')await axios.delete(`/api/es/tasks/${task.id}`);else await axios.post(`/api/es/tasks/${task.id}/${action}`);await loadEsTasks()}catch(e){alert(e)}}
async function loadNebulaTasks(){try{nebulaTasks.value=(await axios.get('/api/nebula/tasks')).data}catch(e){console.error(e)}}
async function connectNebula(){nebulaConnecting.value=true;try{const data=(await axios.post('/api/nebula/connect',nebulaConnection)).data;nebulaSpaces.value=data.spaces;selectedSpaces.value=[];notify(`已连接 NebulaGraph，获取到 ${data.spaces.length} 个 Space。`,'success')}catch(e){alert(e)}finally{nebulaConnecting.value=false}}
function chooseNebulaFiles(event){nebulaFiles.value=[...event.target.files]}
async function submitNebula(){if(nebulaMode.value==='export'&&!selectedSpaces.value.length)return alert('请至少选择一个 Space');if(nebulaMode.value==='import'&&!nebulaFiles.value.length)return alert('请选择 Nebula 导出 ZIP 或备份目录');nebulaSubmitting.value=true;try{if(nebulaMode.value==='export')await axios.post('/api/nebula/tasks/export',{connection:nebulaConnection,spaces:selectedSpaces.value});else{const data=new FormData();nebulaFiles.value.forEach(file=>data.append('files',file,file.webkitRelativePath||file.name));Object.entries(nebulaConnection).forEach(([k,v])=>data.append(k,String(v)));await axios.post('/api/nebula/tasks/import',data);nebulaFiles.value=[];if(nebulaZipInput.value)nebulaZipInput.value.value='';if(nebulaDirInput.value)nebulaDirInput.value.value=''}notify(`Nebula ${nebulaMode.value==='export'?'导出':'导入'}任务已创建。`,'success');selectedSpaces.value=[];await loadNebulaTasks()}catch(e){alert(e)}finally{nebulaSubmitting.value=false}}
async function deleteNebula(task){if(!await ask(`删除后将同时清理任务“${task.name}”及其文件，此操作无法撤销。`))return;try{await axios.delete(`/api/nebula/tasks/${task.id}`);await loadNebulaTasks()}catch(e){alert(e)}}
async function controlTask(task, action){
  if(action==='delete'&&!await ask(`删除后将同时清理“${task.request.options.output_name}”及全部下载文件，此操作无法撤销。`)) return
  try{
    if(action==='delete') await axios.delete(`/api/tasks/${task.id}`)
    else await axios.post(`/api/tasks/${task.id}/${action}`)
    await loadTasks()
  }catch(e){alert(e.response?.data?.detail||e.message)}
}
function statusText(s){return {scheduled:'等待定时执行',queued:'排队中',running:'进行中',paused:'已暂停',completed:'已完成',failed:'失败',cancelled:'已取消'}[s]||s}
function dateText(v){return new Date(v).toLocaleString('zh-CN')}
async function applyAiPatch(patch){
  const target=patch?.target,values=patch?.values||{}
  if(target&&target!==view.value){go(target);await nextTick()}
  if(target==='map'){
    const source=tileSources.find(item=>item.id===values.tile_source)
    if(source){mapCategory.value=source.category;form.data_type=source.type;form.tile_source=source.id}
    else if(values.data_type==='dem'){mapCategory.value='dem';form.data_type='dem'}
    const selectedSource=tileSources.find(item=>item.id===form.tile_source)||availableTileSources.value[0]
    if(selectedSource){form.zoom_min=Math.max(selectedSource.minZoom,Math.min(selectedSource.maxZoom,Number(values.zoom_min??form.zoom_min)));form.zoom_max=Math.max(form.zoom_min,Math.min(selectedSource.maxZoom,Number(values.zoom_max??form.zoom_max)))}
    if(['png','tif'].includes(values.output_format))form.output_format=values.output_format
    if(Number.isInteger(Number(values.max_workers)))form.max_workers=Math.max(1,Math.min(16,Number(values.max_workers)))
  }else if(target==='pdf'){
    if(Array.isArray(values.urls))pdfUrls.value=values.urls.filter(Boolean).join('\n')
    else if(typeof values.urls==='string')pdfUrls.value=values.urls.trim()
    if(typeof values.filename_template==='string'&&values.filename_template.trim())pdfFilenameTemplate.value=values.filename_template.trim().slice(0,160)
  }else if(target==='crawler'){
    if(['generic','news','twitter','tiktok','telegram','youtube','wechat'].includes(values.source))setCrawlerSource(values.source)
    if(['user','history','keyword'].includes(values.twitter_mode))crawlerTwitterMode.value=values.twitter_mode
    if(['keyword','comments','user','videos'].includes(values.tiktok_mode))crawlerTiktokMode.value=values.tiktok_mode
    if(['channel','group','members','search'].includes(values.telegram_mode))crawlerTelegramMode.value=values.telegram_mode
    const maxItems=Number(values.max_items);if(maxItems===-1||(maxItems>=1&&maxItems<=500))crawlerMaxItems.value=maxItems
    if(['xlsx','csv','json','jsonl','postgresql'].includes(values.output_format))crawlerOutputFormat.value=values.output_format
    if(typeof values.download_videos==='boolean'&&crawlerCanDownloadVideos.value)crawlerDownloadVideos.value=values.download_videos
    if([360,720,1080].includes(Number(values.quality)))crawlerYoutubeQuality.value=Number(values.quality)
    if([0,60,360,1440,-1].includes(Number(values.interval)))crawlerInterval.value=Number(values.interval)
    if(typeof values.cron==='string'&&values.cron.trim().split(/\s+/).length===5){crawlerCron.value=values.cron.trim();crawlerInterval.value=-1}
    if(Array.isArray(values.urls))crawlerUrls.value=values.urls.filter(Boolean).join('\n')
    if(typeof values.keyword==='string')crawlerKeyword.value=values.keyword
    if(typeof values.account_name==='string')crawlerAccountName.value=values.account_name
    await loadCrawlerFields()
    if(Array.isArray(values.fields)&&values.fields.length){
      const wanted=new Set(values.fields.map(item=>String(item).trim()).filter(Boolean))
      crawlerFields.value.forEach(field=>field.enabled=wanted.has(field.name))
      for(const fieldName of wanted)if(!crawlerFields.value.some(field=>field.name===fieldName))crawlerFields.value.push({name:fieldName,selector:'',attribute:'text',enabled:true,builtin:false})
    }
  }
  notify('AI 建议配置已填入，请确认后再执行。','success')
}
onMounted(async()=>{
  const crawlerUsesMultipleAccounts=()=>crawlerSource.value==='twitter'&&['user','history'].includes(crawlerTwitterMode.value)||['tiktok','douyin'].includes(crawlerSource.value)&&['user','videos'].includes(crawlerTiktokMode.value)
  const syncCrawlerTargetInput=()=>{const control=document.querySelector('.crawler-keyword-step input,.crawler-keyword-step textarea');if(!control)return;const needsMultiline=crawlerUsesMultipleAccounts();if(needsMultiline&&control.tagName!=='TEXTAREA'){const area=document.createElement('textarea');area.className=control.className;area.rows=3;area.placeholder=['tiktok','douyin'].includes(crawlerSource.value)?`每行一个${crawlerShortVideoLabel.value}账号，例如：@账号1\n@账号2`:'每行一个 X 账号，例如：@OpenAI\n@GoogleAI';area.value=crawlerKeyword.value;area.addEventListener('input',e=>crawlerKeyword.value=e.target.value);control.replaceWith(area)}else if(!needsMultiline&&control.tagName==='TEXTAREA'){const input=document.createElement('input');input.className=control.className;input.placeholder=crawlerSource.value==='twitter'?'例如：地理信息 GIS':'请输入采集目标';input.value=crawlerKeyword.value;input.addEventListener('input',e=>crawlerKeyword.value=e.target.value);control.replaceWith(input)}}
  setTimeout(syncCrawlerTargetInput,300);watch([crawlerSource,crawlerTwitterMode,crawlerTiktokMode],()=>{crawlerKeyword.value='';setTimeout(syncCrawlerTargetInput,50)});
  window.addEventListener('hashchange',syncHash)
  await nextTick(); map.value=L.map(mapEl.value,{zoomControl:true}).setView([31.23,121.47],11)
  demLayer=createDemLayer();switchMapType()
  map.value.pm.addControls({position:'topleft',drawMarker:false,drawCircle:false,drawCircleMarker:false,drawPolyline:false,drawPolygon:false,drawText:false,editMode:true,dragMode:false,cutPolygon:false,removalMode:true,rotateMode:false})
  map.value.on('pm:create',e=>{if(e.shape==='Rectangle')layers.value=[...layers.value,{layer:e.layer,layerId:mapLayerId(e.layer),geometry:null,name:null}]})
  map.value.on('pm:remove',e=>removeAreaByMapLayer(e.layer))
  map.value.on('layerremove',e=>removeAreaByMapLayer(e.layer))
  await Promise.all([loadTasks(),loadDockerTasks(),loadGjbTasks(),loadEsTasks(),loadNebulaTasks(),loadVersions(),loadPdfTasks(),loadMdWordTasks(),loadImageTasks(),loadDatabaseTasks(),loadPropzoneTasks(),loadCrawlerTasks(),loadCrawlerCapabilities()]);if(view.value==='shp')await nextTick(initShpMap);if(view.value==='propzone')await nextTick(initPropzoneMap);if(view.value==='trending')await loadTrendingDates();if(view.value==='crawler')await loadCrawlerFields(); timer=setInterval(()=>{loadTasks();loadDockerTasks();loadGjbTasks();loadEsTasks();loadNebulaTasks();loadPdfTasks();loadMdWordTasks();loadImageTasks();loadDatabaseTasks();loadPropzoneTasks();loadCrawlerTasks()},2000)
})
onBeforeUnmount(()=>{clearInterval(timer);window.removeEventListener('hashchange',syncHash);gjbMap?.remove();shpMap?.remove();propzoneMap?.remove()})
</script>

<template>
  <main class="ui-shell" :class="{'is-portal':view==='home'}">
    <div class="toast-stack" aria-live="polite"><TransitionGroup name="toast"><div v-for="item in toasts" :key="item.id" class="toast-card" :class="item.type"><div class="toast-icon">{{item.type==='success'?'✓':item.type==='info'?'i':'!'}}</div><div><b>{{item.title}}</b><p>{{item.message}}</p></div><button aria-label="关闭" @click="toasts=toasts.filter(x=>x.id!==item.id)">×</button></div></TransitionGroup></div>
    <Teleport to="body"><Transition name="modal"><div v-if="confirmDialog.open" class="modal-mask" @click.self="settleConfirm(false)"><div class="confirm-card" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><div class="confirm-head"><div class="confirm-symbol"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 8v9m4-9v9m4-9v9M5 5h14m-9-2h4l1 2m3 0-1 16H7L6 5"/></svg></div><div><h3 id="confirm-title">{{confirmDialog.title}}</h3><small>删除后无法恢复</small></div></div><p>{{confirmDialog.message}}</p><div class="confirm-actions"><button class="cancel-btn" @click="settleConfirm(false)">取消</button><button class="confirm-btn" @click="settleConfirm(true)">确认删除</button></div></div></div></Transition></Teleport>
    <button v-if="view!=='home'" class="back-home" @click="go('home')">← 返回工具门户</button>
    <ToolPortal v-if="view==='home'" :icon-component="AiIcon" @open="go" />
    <AiAssistant :current-view="view" :context="aiContext" @navigate="go" @apply-config="applyAiPatch" />
    <TilePreviewTool v-if="view==='tile-viewer'" :confirm-action="ask" @notify="(message,type)=>notify(message,type)" />
    <section v-if="view==='crawler'" class="crawler-page" :class="{'crawler-account-mode':crawlerSource==='twitter'&&crawlerTwitterMode!=='keyword'}">
      <header class="crawler-hero"><div class="crawler-hero-copy"><div class="crawler-hero-symbol"><AiIcon name="layers" /></div><div><span class="eyebrow">SMART WEB COLLECTION</span><h1>智能网页采集</h1><p>按来源完成搜索、发现与字段提取，将公开内容整理为可交付数据。</p></div></div><div class="crawler-hero-pills"><span>公开数据</span><span>可视化选取</span><span>定时导出</span></div></header>
      <div class="crawler-workspace"><aside class="panel crawler-config">
        <div class="panel-title"><div><b>配置采集任务</b><small>按顺序完成来源、目标、字段和输出设置</small></div><span>4 步完成</span></div>
        <ol class="crawler-progress" aria-label="任务配置步骤"><li class="active"><i>1</i><span>数据来源</span></li><li :class="{active:crawlerInputReady}"><i>2</i><span>采集目标</span></li><li :class="{active:crawlerFields.some(field=>field.enabled!==false)}"><i>3</i><span>提取内容</span></li><li><i>4</i><span>保存方式</span></li></ol>
        <div class="crawler-step"><b><i>1</i> 选择数据来源</b><small class="crawler-step-help">每种来源使用独立的搜索、发现和内容解析流程</small><div class="crawler-source-cards"><button v-for="item in [{value:'generic',label:'普通网页',icon:'◎'},{value:'news',label:'新闻网站',icon:'▤'},{value:'twitter',label:'推特 / X',icon:'𝕏'},{value:'tiktok',label:'TikTok',icon:'♪'},{value:'douyin',label:'抖音',icon:'音'},{value:'telegram',label:'Telegram',icon:'➤'},{value:'youtube',label:'YouTube',icon:'▶'},{value:'wechat',label:'微信公众号',icon:'微'}]" :key="item.value" :class="{active:crawlerSource===item.value}" @click="setCrawlerSource(item.value)"><i>{{item.icon}}</i><span>{{item.label}}</span></button></div><div v-if="crawlerSource==='twitter'" class="crawler-twitter-modes"><button v-for="item in [{value:'user',label:'用户信息',help:'账号资料'},{value:'history',label:'历史推文',help:'指定账号'},{value:'keyword',label:'关键词推文',help:'全网发现'}]" :key="item.value" :class="{active:crawlerTwitterMode===item.value}" @click="setCrawlerTwitterMode(item.value)"><b>{{item.label}}</b><small>{{item.help}}</small></button></div><div v-if="['tiktok','douyin'].includes(crawlerSource)" class="crawler-tiktok-modes"><button v-for="item in [{value:'keyword',label:'关键词视频',help:'搜索发现'},{value:'comments',label:'视频评论',help:'视频链接'},{value:'user',label:'账号信息',help:'公开资料'},{value:'videos',label:'账号视频',help:'历史作品'}]" :key="item.value" :class="{active:crawlerTiktokMode===item.value}" @click="setCrawlerTiktokMode(item.value)"><b>{{item.label}}</b><small>{{item.help}}</small></button></div><div v-if="crawlerSource==='telegram'" class="crawler-telegram-modes"><button v-for="item in [{value:'channel',label:'频道采集',help:'公开消息'},{value:'group',label:'群组采集',help:'群组消息'},{value:'members',label:'群组成员',help:'成员资料'},{value:'search',label:'全平台搜索',help:'关键词'}]" :key="item.value" :class="{active:crawlerTelegramMode===item.value}" @click="setCrawlerTelegramMode(item.value)"><b>{{item.label}}</b><small>{{item.help}}</small></button></div></div>
        <div v-if="crawlerSource==='wechat'" class="crawler-wechat-target"><label class="crawler-url-step crawler-account-step"><b><i>2</i> 输入公众号名称</b><small>无需登录，可获取公开索引；平台允许访问原文时继续采集正文</small><input v-model="crawlerAccountName" placeholder="请输入准确的公众号全称"></label><div class="crawler-or"><span>或者</span></div><label class="crawler-direct-urls"><b>粘贴已知微信文章链接</b><small>可选；每行一个，系统将直接采集文章正文</small><textarea v-model="crawlerUrls" rows="3" placeholder="https://mp.weixin.qq.com/s/..."></textarea></label></div>
        <label v-else-if="['youtube','twitter','tiktok','douyin','telegram'].includes(crawlerSource)" class="crawler-url-step crawler-keyword-step"><b><i>2</i> {{crawlerSource==='telegram'?(crawlerTelegramMode==='search'?'输入全平台搜索关键词':'输入频道或群组'):crawlerSource==='twitter'&&crawlerTwitterMode!=='keyword'?'输入 X 账号':['tiktok','douyin'].includes(crawlerSource)?(crawlerTiktokMode==='comments'?`输入${crawlerShortVideoLabel}视频链接`:crawlerTiktokMode==='keyword'?'输入搜索关键词':`输入${crawlerShortVideoLabel}账号`):'输入搜索关键词'}}</b><small>{{crawlerSource==='telegram'?(crawlerTelegramMode==='search'?'从已授权会话可见范围内搜索公开消息':'支持 @名称 或 t.me 公开链接'):crawlerSource==='youtube'?'按关键词搜索公开视频':['tiktok','douyin'].includes(crawlerSource)?(crawlerTiktokMode==='comments'?'读取该公开视频下可见评论':crawlerTiktokMode==='user'?'读取账号公开资料，无需 API Key':crawlerTiktokMode==='videos'?'查找指定账号的公开历史视频':'按关键词查找 TikTok 公开视频'):crawlerTwitterMode==='user'?'读取账号公开资料，无需 API Token':crawlerTwitterMode==='history'?'采集指定账号的公开历史推文':'通过公开索引查找包含关键词的推文'}}</small><textarea v-if="['tiktok','douyin'].includes(crawlerSource)&&['user','videos'].includes(crawlerTiktokMode)" v-model="crawlerKeyword" rows="3" placeholder="每行一个账号，例如：@账号名"></textarea><input v-else v-model="crawlerKeyword" :placeholder="crawlerSource==='telegram'?(crawlerTelegramMode==='search'?'例如：人工智能 GIS':'例如：@telegram 或 https://t.me/telegram'):crawlerSource==='youtube'?'例如：人工智能 地图':['tiktok','douyin'].includes(crawlerSource)?(crawlerTiktokMode==='comments'?'https://www.tiktok.com/@user/video/123...':crawlerTiktokMode==='keyword'?'例如：城市旅行 或 #GIS':'例如：@tiktok'):crawlerTwitterMode==='keyword'?'例如：地理信息 GIS':'例如：@OpenAI 或 OpenAI'"></label>
        <label v-else class="crawler-url-step"><b><i>2</i> {{crawlerSource==='news'?'粘贴新闻列表页地址':'粘贴要采集的网页地址'}}</b><small>{{crawlerSource==='news'?'支持栏目页、频道页；每行一个':'每行一个，可以一次粘贴多个'}}</small><textarea v-model="crawlerUrls" :rows="crawlerSource==='news'?4:5" :placeholder="crawlerSource==='news'?'例如：https://www.chinanews.com.cn/world/':'例如：https://example.com/article'"></textarea></label>
        <section v-if="crawlerSource==='telegram'&&['members','search'].includes(crawlerTelegramMode)" class="crawler-telegram-auth"><div><b>Telegram 官方 API 授权</b><small>{{crawlerCapabilities.telegram_api_configured?'服务器已配置授权信息，也可以在此覆盖。':'当前模式必须填写；凭据仅保存在本机任务数据中，接口展示时自动脱敏。'}}</small></div><div v-if="!crawlerCapabilities.telegram_api_configured" class="crawler-telegram-auth-grid"><label>API ID<input v-model.trim="crawlerTelegram.api_id" inputmode="numeric" placeholder="my.telegram.org 获取"></label><label>API Hash<div class="password-field"><input v-model="crawlerTelegram.api_hash" :type="showCrawlerTelegramSecrets?'text':'password'" autocomplete="off"><button type="button" @click="showCrawlerTelegramSecrets=!showCrawlerTelegramSecrets">{{showCrawlerTelegramSecrets?'隐藏':'显示'}}</button></div></label><label class="crawler-telegram-session">授权会话字符串<textarea v-model="crawlerTelegram.session" :class="{masked:!showCrawlerTelegramSecrets}" rows="2" placeholder="Telethon StringSession"></textarea></label></div></section>
        <div v-if="crawlerSource!=='generic'" class="crawler-discovery-box"><div><b>{{crawlerSource==='news'?'自动查找新闻详情':crawlerSource==='wechat'?'查找公开历史文章':crawlerSource==='youtube'?'搜索并下载 YouTube 视频':['tiktok','douyin'].includes(crawlerSource)?crawlerTiktokActionLabel:crawlerSource==='telegram'?crawlerTelegramActionLabel:crawlerTwitterMode==='user'?'读取公开用户资料':crawlerTwitterMode==='history'?'采集用户历史推文':'搜索关键词推文'}}</b><small v-if="crawlerSource==='news'">自动识别新闻链接，并处理下一页、分页和滚动加载。</small><small v-else-if="crawlerSource==='wechat'">按名称查找公众号文章；可访问详情时采集正文，否则保留公开索引。</small><small v-else-if="crawlerSource==='youtube'">按关键词搜索公开视频，任务执行时下载视频并与 Excel 数据表一起打包为 ZIP。</small><small v-else-if="['tiktok','douyin'].includes(crawlerSource)">{{crawlerTiktokMode==='comments'?'滚动加载公开视频评论并去重；登录或验证码页面会停止并提示。':crawlerTiktokMode==='user'?'读取账号简介、粉丝、获赞、视频数和头像等公开资料。':crawlerTiktokMode==='videos'?'读取指定账号的公开作品列表及视频指标。':'从 TikTok 搜索页发现关键词相关公开视频及指标。'}}</small><small v-else-if="crawlerSource==='telegram'">{{crawlerTelegramMode==='members'?'读取授权账号有权查看的群组成员公开资料。':crawlerTelegramMode==='search'?'在授权账号可见范围内搜索消息并保存来源。':crawlerTelegramMode==='group'?'采集公开群组消息、媒体链接和互动信息。':'采集公开频道消息、媒体链接和互动信息。'}}</small><small v-else-if="crawlerTwitterMode==='user'">获取用户名、简介、位置、粉丝数、关注数、推文数、认证状态和头像等公开资料。</small><small v-else-if="crawlerTwitterMode==='history'">从 X 官方公开账号时间线读取历史推文，再通过官方嵌入接口补全正文。</small><small v-else>通过公开网页索引发现包含关键词的推文，再由 X 官方嵌入接口读取正文。</small></div><label v-if="!(crawlerSource==='twitter'&&crawlerTwitterMode==='user')&&!(['tiktok','douyin'].includes(crawlerSource)&&crawlerTiktokMode==='user')">最多采集<input v-model.number="crawlerMaxItems" type="number" min="-1" max="500" step="1" inputmode="numeric" placeholder="输入数量"><small>-1：持久化增量采集，定时执行自动去重；1～500 {{crawlerSource==='twitter'?'条推文':['tiktok','douyin'].includes(crawlerSource)?(crawlerTiktokMode==='comments'?'条评论':'个视频'):crawlerSource==='telegram'?(crawlerTelegramMode==='members'?'个成员':'条消息'):crawlerSource==='youtube'?'个视频':'篇文章'}}</small></label><button class="crawler-data-preview-btn" :disabled="!crawlerInputReady||!crawlerFields.some(field=>field.enabled!==false)||crawlerDataPreviewLoading" @click="previewCrawlerData">{{crawlerDataPreviewLoading?'正在读取样本…':'预览采集数据'}}</button></div>
        <div v-else class="crawler-analyze"><span>如果默认内容不准确，可先识别字段或预览第一批数据。</span><div><button @click="analyzeCrawler" :disabled="crawlerAnalyzing||!crawlerUrls.trim()">{{crawlerAnalyzing?'正在查看网页…':'识别网页内容'}}</button><button class="crawler-data-preview-btn" @click="previewCrawlerData" :disabled="!crawlerInputReady||!crawlerFields.some(field=>field.enabled!==false)||crawlerDataPreviewLoading">{{crawlerDataPreviewLoading?'正在读取样本…':'预览采集数据'}}</button></div></div>
        <div class="crawler-fields"><div class="crawler-fields-head"><b><i>3</i> 选择要保存的内容</b><div><button v-if="!['twitter','tiktok','douyin','telegram','youtube'].includes(crawlerSource)" type="button" class="crawler-visual-pick-btn" @click="openCrawlerPicker">＋ 页面点选字段</button><button type="button" @click="crawlerFields.forEach(field=>field.enabled=true)">全选</button><button type="button" @click="crawlerFields.forEach(field=>field.enabled=false)">清空</button><small>{{crawlerFields.filter(field=>field.enabled!==false).length}} 项</small></div></div><div class="crawler-simple-fields"><label v-for="(field,index) in crawlerFields" :key="index" :class="{active:field.enabled!==false}"><input v-model="field.enabled" type="checkbox"><span>{{crawlerFieldLabel(field.name)}}</span></label></div><small class="crawler-fields-tip">默认字段已按当前来源和采集模式配置，可直接勾选需要导出的内容。</small></div>
        <section v-if="crawlerPickerOpen" class="crawler-picker"><div class="crawler-picker-head"><div><b>页面点选字段</b><small>{{crawlerPickerLoading?'正在用浏览器打开页面…':`浏览器渲染：${crawlerPreviewUrl}`}}</small></div><button @click="crawlerPickerOpen=false">关闭</button></div><div v-if="crawlerPickerLoading" class="crawler-picker-loading">正在等待网页完成跳转、渲染和图片加载，请稍候…</div><template v-else><div class="crawler-picker-toolbar"><div><b>{{crawlerPickedSelector?'已选中页面内容':'请在下方真实页面渲染结果中点击要保存的文字或图片'}}</b><small v-if="crawlerPickedText">示例：{{crawlerPickedText}}</small></div><input v-model="crawlerPickedName" placeholder="字段名称，如：栏目"><select v-model="crawlerPickedAttribute"><option value="text">提取文字</option><option value="src">图片地址</option><option v-if="['data-src','data-original','data-lazy-src'].includes(crawlerPickedAttribute)" :value="crawlerPickedAttribute">图片地址（懒加载）</option><option value="href">链接地址</option></select><button :disabled="!crawlerPickedSelector" @click="addCrawlerPickedField">添加字段</button></div><iframe ref="crawlerPreviewFrame" title="字段点选页面预览" :sandbox="crawlerSource==='youtube'?'allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-presentation allow-forms':'allow-same-origin'" :allow="crawlerSource==='youtube'?'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share':undefined" :srcdoc="crawlerPreviewHtml" @load="bindCrawlerPreview"></iframe></template></section>
        <div class="crawler-finish"><b><i>4</i> 选择保存方式</b><label v-if="crawlerSource==='generic'" class="crawler-generic-limit">最多采集<input v-model.number="crawlerMaxItems" type="number" min="-1" max="500" step="1"><small>-1：持久化增量采集，定时执行自动去重</small></label><div class="grid2"><label>保存为<select v-model="crawlerOutputFormat"><option value="xlsx">Excel 表格（推荐）</option><option value="csv">CSV 表格</option><option value="json">JSON 数据</option><option value="jsonl">JSONL 数据</option><option value="postgresql">PostgreSQL 数据库</option></select></label><label v-if="crawlerCanDownloadVideos" class="crawler-download-toggle"><span><input v-model="crawlerDownloadVideos" type="checkbox"> 是否下载视频文件</span><small>勾选后与 Excel 数据表一起打包为 ZIP</small></label><label v-if="crawlerCanDownloadVideos">视频清晰度<select v-model.number="crawlerYoutubeQuality"><option :value="360">360p · 节省空间</option><option :value="720">720p · 推荐</option><option :value="1080">1080p · 高清</option></select></label><label>执行时间<select v-model.number="crawlerInterval"><option :value="0">立即采集一次</option><option :value="60">每小时自动采集</option><option :value="360">每 6 小时自动采集</option><option :value="1440">每天自动采集</option><option :value="-1">自定义 Cron 时间</option></select></label><div v-if="crawlerInterval===-1" class="crawler-cron"><label>Cron 表达式<input v-model="crawlerCron" placeholder="0 9 * * 1-5" @input="crawlerCronRuns=[]"></label><small>分 时 日 月 周 · 北京时间 · 到点首次执行</small><label>用自然语言描述<input v-model="crawlerCronText" placeholder="例如：每个工作日上午9点"></label><div class="task-actions"><button type="button" :disabled="crawlerCronBusy||!crawlerCronText.trim()" @click="previewCrawlerCron(true)">AI 转换</button><button type="button" :disabled="crawlerCronBusy||!crawlerCron.trim()" @click="previewCrawlerCron(false)">校验执行时间</button></div><small v-if="crawlerCronBusy">正在解析…</small><section v-if="crawlerCronRuns.length" class="crawler-cron-results" aria-live="polite"><div class="crawler-cron-results-head"><b>未来三次执行</b><span>北京时间</span></div><ol><li v-for="(time,index) in crawlerCronRuns" :key="time"><span class="crawler-cron-order">{{index+1}}</span><time :datetime="time">{{formatCronRun(time)}}</time><span v-if="index===0" class="crawler-cron-next">下次</span></li></ol></section></div></div><section v-if="crawlerOutputFormat==='postgresql'" class="crawler-sql-config"><div class="crawler-sql-grid"><label>主机地址<input v-model.trim="crawlerSql.host" placeholder="127.0.0.1" @input="crawlerSqlTested=false"></label><label>端口<input v-model.number="crawlerSql.port" type="number" min="1" max="65535" @input="crawlerSqlTested=false"></label><label>数据库名<input v-model.trim="crawlerSql.database" placeholder="crawler" @input="crawlerSqlTested=false"></label><label>用户名<input v-model.trim="crawlerSql.username" autocomplete="off" @input="crawlerSqlTested=false"></label><label>密码<div class="password-field"><input v-model="crawlerSql.password" :type="showCrawlerSqlPassword?'text':'password'" autocomplete="new-password" @input="crawlerSqlTested=false"><button type="button" :aria-label="showCrawlerSqlPassword?'隐藏密码':'显示密码'" @click="showCrawlerSqlPassword=!showCrawlerSqlPassword">{{showCrawlerSqlPassword?'隐藏':'显示'}}</button></div></label><label>SSL 模式<select v-model="crawlerSql.sslmode" @change="crawlerSqlTested=false"><option value="prefer">优先使用 SSL</option><option value="require">必须使用 SSL</option><option value="disable">不使用 SSL</option></select></label><label>Schema<input v-model.trim="crawlerSql.schema" placeholder="public" @input="crawlerSqlTested=false"></label><label>数据表<input v-model.trim="crawlerSql.table" placeholder="crawler_data" @input="crawlerSqlTested=false"></label></div><div class="crawler-sql-actions"><button type="button" :disabled="crawlerSqlTesting" @click="testCrawlerSql">{{crawlerSqlTesting?'连接中…':'测试数据库连接'}}</button><span v-if="crawlerSqlTested">✓ 已连接，任务执行时自动建表</span></div></section></div>
        <section v-if="crawlerDataPreviewOpen||crawlerDataPreview" class="crawler-data-preview" :class="{collapsed:!crawlerDataPreviewOpen}"><div class="crawler-data-preview-head"><div><b>采集前数据预览</b><small v-if="crawlerDataPreview">已读取 {{crawlerDataPreview.sampled}} 条样本 · 当前字段：{{crawlerDataPreview.columns.map(crawlerPreviewLabel).join('、')}}</small><small v-else>将按当前勾选字段生成预览</small></div><div class="crawler-data-preview-actions"><button v-if="crawlerDataPreview&&!crawlerDataPreviewLoading&&!crawlerDataPreviewError" type="button" :class="{active:crawlerPreviewTable}" @click="crawlerPreviewTable=!crawlerPreviewTable">{{crawlerPreviewTable?'卡片视图':'表格视图'}}</button><button type="button" @click="crawlerDataPreviewOpen=!crawlerDataPreviewOpen">{{crawlerDataPreviewOpen?'收起预览':'展开预览'}}</button></div></div><div v-if="crawlerDataPreviewLoading" class="crawler-data-preview-loading">正在按当前勾选字段读取少量公开样本…</div><div v-else-if="crawlerDataPreviewError" class="crawler-data-preview-error">{{crawlerDataPreviewError}}<button type="button" @click="previewCrawlerData">重试</button></div><template v-else-if="crawlerDataPreview"><div v-if="crawlerPreviewTable||crawlerDataPreview.mode==='table'" class="crawler-preview-table-wrap"><table><thead><tr><th v-for="column in crawlerDataPreview.columns" :key="column">{{crawlerPreviewLabel(column)}}</th></tr></thead><tbody><tr v-for="(row,index) in crawlerDataPreview.rows" :key="index"><td v-for="column in crawlerDataPreview.columns" :key="column">{{crawlerPreviewText(row[column])}}</td></tr></tbody></table></div><div v-else class="crawler-preview-cards" :class="`mode-${crawlerDataPreview.mode}`"><article v-for="(row,index) in crawlerDataPreview.rows" :key="index"><div v-if="crawlerPreviewImages(row.thumbnail||row.image).length" class="crawler-preview-card-images"><img v-for="image in crawlerPreviewVisibleImages(row.thumbnail||row.image)" :key="image" :src="image" alt="" referrerpolicy="no-referrer"><span v-if="crawlerPreviewImages(row.thumbnail||row.image).length>4" class="crawler-preview-image-count">+{{crawlerPreviewImages(row.thumbnail||row.image).length-4}} 张</span></div><div class="crawler-preview-card-body"><small v-if="row.channel||row.author||row.account">{{row.channel||row.author||row.account}}</small><h3 v-if="row.title||row.text">{{row.title||row.text}}</h3><p v-if="row.description||row.content">{{crawlerPreviewText(row.description||row.content)}}</p><div class="crawler-preview-meta"><span v-for="column in crawlerDataPreview.columns.filter(name=>!['title','text','description','content','image','thumbnail','url'].includes(name)&&row[name])" :key="column">{{crawlerPreviewLabel(column)}}：{{crawlerPreviewText(row[column])}}</span></div><a v-if="crawlerDataPreview.columns.includes('url')&&row.url" :href="row.url" target="_blank" rel="noreferrer">查看来源 ↗</a></div></article></div></template></section>
        <details class="crawler-advanced"><summary>网页加载有问题？ <small>展开高级设置</small></summary><div class="crawler-advanced-body"><p class="crawler-advanced-tip">通常无需修改。只有系统没有找到内容或页面时，才需要调整以下设置。</p><div v-if="crawlerSource==='news'" class="crawler-discovery-advanced"><label>新闻链接规则<input v-model="crawlerArticleSelector" placeholder="可不填，例如：.news-list h2 a"></label><label>下一页按钮规则<input v-model="crawlerNextPageSelector" placeholder="可不填，例如：a.next"></label></div><div class="crawler-advanced-fields"><b>自定义内容位置</b><label v-for="(field,index) in crawlerFields" :key="index" class="crawler-field-row"><input v-model="field.name" placeholder="内容名称"><input v-model="field.selector" placeholder="页面元素规则；留空自动识别"><select v-model="field.attribute"><option value="text">文字</option><option value="content">说明文字</option><option value="href">链接</option><option value="src">图片地址</option><option value="datetime">时间</option></select><button type="button" aria-label="删除此项" @click="crawlerFields.splice(index,1)">×</button></label><button class="crawler-add-field" @click="crawlerFields.push({name:'custom_field',selector:'',attribute:'text',enabled:true})">＋ 添加自定义内容</button></div><label>代理地址（可不填）<textarea v-model="crawlerProxies" rows="2" placeholder="每行填写一个代理地址"></textarea></label><label>每次访问间隔<input v-model.number="crawlerDelay" type="number" min="0.2" step="0.1"><small>秒，建议保持默认值</small></label><div class="crawler-options"><label><input v-model="crawlerDynamic" type="checkbox">详情内容需要滚动或等待后才显示</label></div></div></details>
        <div class="crawler-summary"><span>✓</span><div><b>{{crawlerInputReady?'可以开始采集':'还差第 2 步'}}</b><small>{{crawlerTargetSummary}} · {{crawlerFields.filter(x=>x.enabled!==false).length}} 项内容 · {{crawlerCanDownloadVideos?(crawlerDownloadVideos?`ZIP + ${crawlerYoutubeQuality}p 视频`:'XLSX 数据表'):crawlerOutputFormat.toUpperCase()}}</small></div></div>
        <button class="primary crawler-submit" :disabled="crawlerSubmitting||!crawlerInputReady" @click="submitCrawler">{{crawlerSubmitting?'正在创建…':crawlerSource==='news'?'查找并采集新闻':crawlerSource==='wechat'?'查找公众号文章':crawlerSource==='youtube'?'搜索并采集视频':crawlerSource==='twitter'?crawlerTwitterActionLabel:['tiktok','douyin'].includes(crawlerSource)?crawlerTiktokActionLabel:crawlerSource==='telegram'?crawlerTelegramActionLabel:'开始采集'}}</button>
      </aside></div>
      <section class="queue crawler-queue"><div class="queue-head crawler-task-head"><div class="crawler-task-heading"><span class="eyebrow">MY COLLECTION TASKS</span><h2>我的采集任务</h2><p>{{crawlerTaskTab==='scheduled'?'管理长期增量采集、查看下次执行和累计数据。':'查看一次性采集进度，并下载本次整理结果。'}}</p></div><div class="crawler-task-toolbar"><nav class="crawler-task-tabs" aria-label="采集任务类型"><button type="button" :class="{active:crawlerTaskTab==='single'}" @click="crawlerTaskTab='single'"><span>单次任务</span><i>{{crawlerSingleTasks.length}}</i></button><button type="button" :class="{active:crawlerTaskTab==='scheduled'}" @click="crawlerTaskTab='scheduled'"><span>定时任务</span><i>{{crawlerScheduledTasks.length}}</i></button></nav><button class="refresh crawler-task-refresh" @click="loadCrawlerTasks">刷新</button></div></div><div v-if="!crawlerVisibleTasks.length" class="empty crawler-tab-empty">{{crawlerTaskTab==='scheduled'?'还没有定时任务，创建任务时选择自动执行时间即可。':'还没有单次任务，请先在上方创建采集任务。'}}</div><article v-for="task in crawlerVisibleTasks" :key="task.id" class="task crawler-task"><div class="task-main"><div class="task-icon"><AiIcon name="layers" /></div><div><b>{{crawlerTaskTitle(task)}}</b><small>{{dateText(task.created_at)}} · {{crawlerSourceLabel(task.request?.source)}} · {{task.current||0}}/{{task.total||0}} {{crawlerSourceUnit(task.request?.source)}}</small><small v-if="['youtube','tiktok','douyin'].includes(task.request?.source)&&task.result?.video_count" class="crawler-video-result">ZIP 内含 {{task.result.video_count}} 个视频和 Excel 数据表</small><small v-if="crawlerIsScheduled(task)&&task.result?.cumulative?.total" class="crawler-cumulative-total">累计已保存 {{task.result.cumulative.total}} 条唯一数据</small><small v-if="crawlerIsScheduled(task)&&task.schedule_paused" class="crawler-schedule-paused">定时调度已暂停</small><small v-if="task.result?.sql" class="crawler-sql-result">PostgreSQL {{task.result.sql.table}} · 新增 {{task.result.sql.inserted}} 条 · 去重 {{task.result.sql.duplicates}} 条</small><small v-if="task.result?.index_only_count" class="crawler-index-warning">其中 {{task.result.index_only_count}} 篇受平台限制，仅包含公开索引信息</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><div v-if="crawlerIsScheduled(task)&&task.next_run_at&&!task.schedule_paused" class="crawler-next-run"><span>下次采集</span><time :datetime="task.next_run_at">{{formatCronRun(task.next_run_at)}}</time></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><button v-if="crawlerIsScheduled(task)&&!task.schedule_paused" class="crawler-schedule-control" @click="controlCrawler(task,'pause_schedule')">暂停定时</button><button v-if="crawlerIsScheduled(task)&&task.schedule_paused" class="resume crawler-schedule-control" @click="controlCrawler(task,'resume_schedule')">恢复定时</button><button v-if="task.status==='running'||task.status==='queued'" @click="controlCrawler(task,'pause')">暂停本次</button><button v-if="task.status==='paused'" class="resume" @click="controlCrawler(task,'resume')">继续</button><button v-if="task.status==='failed'||task.status==='completed'" class="retry" @click="controlCrawler(task,'retry')">重新采集</button><a v-if="(task.runs||[]).some(run=>run.result?.row_count)" :href="`/api/crawler/tasks/${task.id}/export`">{{crawlerIsScheduled(task)?'下载全部数据':['youtube','tiktok','douyin'].includes(task.request?.source)?(task.request?.download_videos?'下载 ZIP':'下载结果'):'下载结果'}}</a><button v-if="crawlerIsScheduled(task)&&task.runs?.length" class="crawler-runs-btn" @click="toggleCrawlerRuns(task)">{{crawlerRunOpen[task.id]?'收起记录':'执行记录'}} {{task.runs.length}}</button><button class="danger" @click="controlCrawler(task,'delete')">删除</button></div><section v-if="crawlerIsScheduled(task)&&crawlerRunOpen[task.id]" class="crawler-run-history"><div class="crawler-run-history-head"><b>执行记录</b><small>最近 {{task.runs.length}} 次，最新记录在前</small></div><div class="crawler-run-list"><article v-for="run in crawlerRunList(task)" :key="run.id" class="crawler-run-item"><div class="crawler-run-main"><span class="crawler-run-index">#{{run.sequence}}</span><div><b>{{crawlerRunTrigger(run.trigger)}}</b><small>{{dateText(run.started_at)}}<template v-if="run.finished_at"> → {{dateText(run.finished_at)}}</template></small></div></div><span class="badge" :class="run.status">{{statusText(run.status)}}</span><div class="crawler-run-progress"><div><span>{{run.message}}</span><strong>{{run.progress||0}}%</strong></div><div class="track"><i :class="run.status" :style="{width:(run.progress||0)+'%'}"></i></div><small>{{run.current||0}}/{{run.total||0}} {{crawlerSourceUnit(task.request?.source)}}</small></div><div class="crawler-run-result"><small v-if="run.result?.row_count">采集 {{run.result.row_count}} 条</small><small v-if="run.result?.sql">数据库新增 {{run.result.sql.inserted}} 条，去重 {{run.result.sql.duplicates}} 条</small><small v-if="run.error" class="error">{{run.error}}</small><a v-if="run.status==='completed'&&run.result?.file" :href="'/api/crawler/tasks/'+task.id+'/runs/'+run.id+'/export'">下载本次结果</a></div></article></div></section></article></section>
    </section>
    <WordBatchTool v-if="view==='word-batch'" :confirm-action="ask" @notify="(message,type)=>notify(message,type)" />
    <ImageMetadataTool v-if="view==='image-metadata'" :confirm-action="ask" @notify="(message,type)=>notify(message,type)" />
    <section v-if="view==='image-convert'" class="image-convert-page">
      <header><div><span class="eyebrow">IMAGE FORMAT CONVERTER</span><h1>图片格式转换</h1><p>批量转换 HEIC、JPEG、PNG、WebP、TIFF 等格式，保留照片元数据与目录结构。</p></div></header>
      <div class="image-convert-workspace">
        <aside class="panel image-convert-config">
          <div class="panel-title"><b>转换配置</b><span>HEIC READY</span></div>
          <div class="image-upload-grid">
            <label>上传图片<input ref="imageFileInput" type="file" multiple :accept="imageAccept" @change="chooseImageFiles"></label>
            <label>上传目录<input ref="imageDirInput" type="file" multiple webkitdirectory directory :accept="imageAccept" @change="chooseImageFiles"></label>
          </div>
          <div class="file-summary image-file-summary">
            <template v-if="imageSelection.count"><b>{{imageSelection.count}} 张图片</b><span>{{formatBytes(imageSelection.size)}} · HEIC/HEIF {{imageSelection.heic}} 张</span></template>
            <template v-else>请选择单张、多张图片或整个图片目录</template>
          </div>
          <div class="grid2 image-output-options">
            <label>输出格式<select v-model="imageOutputFormat"><option value="heic">HEIC</option><option value="jpeg">JPEG</option><option value="png">PNG</option><option value="webp">WebP</option><option value="tiff">TIFF</option></select></label>
            <label>输出质量<input v-model.number="imageQuality" type="number" min="1" max="100" :disabled="!imageLossyOutput"><small>{{imageLossyOutput?'用于 HEIC / JPEG / WebP':'无损格式无需设置质量'}}</small></label>
          </div>
          <div class="hint">自动保留 EXIF/GPS、拍摄时间、ICC 色彩配置和 XMP；根据 EXIF 方向校正像素后统一写入标准方向。目录上传的相对层级会保留到结果 ZIP。</div>
          <button class="primary image-convert-submit" :disabled="imageSubmitting||!imageFiles.length" @click="submitImageConvert">{{imageSubmitting?'正在上传…':'创建转换任务'}}</button>
        </aside>
        <div class="image-convert-guide">
          <div class="image-guide-art"><AiIcon name="image" /><span>HEIC · JPG · PNG</span><i>⇄</i><span>WEBP · TIFF · HEIC</span></div>
          <div><span class="eyebrow">METADATA FIRST</span><h2>格式变化，照片信息仍然随行</h2><p>适合整理 iPhone HEIC 照片、跨平台交付图片，以及保留原目录结构的批量归档转换。</p></div>
          <ul><li><b>输入</b><span>HEIC / HEIF / JPEG / PNG / WebP / TIFF / BMP</span></li><li><b>输出</b><span>HEIC / JPEG / PNG / WebP / TIFF</span></li><li><b>任务限制</b><span>最多 5000 张、单文件 500MB、总计 2GB</span></li></ul>
        </div>
      </div>
      <section class="queue image-convert-queue"><div class="queue-head"><div><span class="eyebrow">IMAGE TASK QUEUE</span><h2>转换任务</h2></div><button class="refresh" @click="loadImageTasks">刷新</button></div><div v-if="!imageTasks.length" class="empty">暂无图片转换任务。</div><article v-for="task in imageTasks" :key="task.id" class="task image-convert-task"><div class="task-main"><div class="task-icon"><AiIcon name="image" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.current}}/{{task.total}} 张 · {{imageTaskOptionText(task)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small><small v-else-if="task.result?.failed" class="image-warning">{{task.result.failed}} 张转换失败，ZIP 中包含其余成功结果</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions image-convert-actions"><a v-if="task.status==='completed'" :href="`/api/image-convert/tasks/${task.id}/export`">下载 ZIP</a><button v-if="task.status==='failed'" class="retry" @click="retryImageTask(task)">重新转换</button><button class="danger" @click="deleteImageTask(task)">删除</button></div></article></section>
    </section>
    <section v-if="view==='database'" class="database-page">
      <header class="database-page-header"><div><span class="eyebrow">DATA WORKBENCH</span><h1>数据库工作台</h1><p>像桌面客户端一样浏览对象、编辑表格数据，并完成数据库迁移。</p></div></header>
      <div class="database-studio">
      <div class="database-connection">
        <div class="database-connection-top">
          <div class="database-connection-title"><div class="database-console-icon"><AiIcon name="data" /></div><div><span class="eyebrow">CONNECTION</span><b>数据连接</b></div><i v-if="databaseConnected">在线</i></div>
          <div class="database-type-tabs"><button v-for="item in [{value:'sqlite',label:'SQLite'},{value:'postgresql',label:'PostgreSQL'},{value:'redis',label:'Redis'}]" :key="item.value" :class="{active:databaseType===item.value}" @click="selectDatabaseType(item.value)">{{item.label}}</button></div>
        </div>
        <div v-if="databaseType==='sqlite'" class="sqlite-file-connect">
          <input ref="databaseSqliteInput" class="sqlite-file-input" type="file" accept=".db,.sqlite,.sqlite3,application/vnd.sqlite3" @change="uploadSqliteFile">
          <button class="sqlite-file-picker" :disabled="databaseSqliteUploading" @click="pickSqliteFile"><span>⌑</span><div><b>{{databaseSqliteUploading?'正在打开…':databaseSqliteFile?'更换 SQLite 文件':'打开 SQLite 文件'}}</b><small>选择本机 .db / .sqlite / .sqlite3</small></div></button>
          <div v-if="databaseSqliteFile" class="sqlite-file-meta"><div class="sqlite-file-symbol"><AiIcon name="data" /></div><div><b>{{databaseSqliteFile.name}}</b><small>{{formatBytes(databaseSqliteFile.size)}}</small></div><span :class="['sqlite-write-state',{warning:!databaseSqliteDirect,error:databaseSqliteSyncError}]"><i></i>{{databaseSqliteSyncing?'正在写入源文件':databaseSqliteSyncError?'源文件写入失败':databaseSqliteDirect?'直接编辑源文件':'兼容读取模式'}}</span><button class="database-close-file" @click="clearSqliteFile">关闭</button></div>
          <details v-if="!databaseSqliteFile" class="sqlite-path-mode"><summary>高级方式：打开服务器文件路径</summary><div><input v-model.trim="databaseConnection.sqlite_path" placeholder="/absolute/path/to/data.db"><button class="primary" :disabled="databaseTesting||!databaseConnection.sqlite_path" @click="testDatabase">{{databaseTesting?'正在打开…':'打开数据库'}}</button></div></details>
        </div>
        <template v-else>
          <div class="database-grid"><label>主机地址<input v-model.trim="databaseConnection.host" placeholder="127.0.0.1"></label><label>端口<input v-model.number="databaseConnection.port" type="number" min="1" max="65535"></label><label v-if="databaseType==='postgresql'">数据库名<input v-model.trim="databaseConnection.database" placeholder="postgres"></label><label v-else>数据库编号<input v-model.number="databaseConnection.redis_db" type="number" min="0"></label><label>用户名 <small>可选</small><input v-model.trim="databaseConnection.username" autocomplete="off"></label><label>密码<div class="password-field"><input v-model="databaseConnection.password" :type="showDatabasePassword?'text':'password'" autocomplete="new-password"><button type="button" :aria-label="showDatabasePassword?'隐藏密码':'显示密码'" @click="showDatabasePassword=!showDatabasePassword"><svg v-if="showDatabasePassword" viewBox="0 0 24 24"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.8"/></svg><svg v-else viewBox="0 0 24 24"><path d="m3 3 18 18M10.6 6.2A10.5 10.5 0 0 1 12 6c6 0 9.5 6 9.5 6a15 15 0 0 1-2.1 2.8M6.2 6.2C3.8 8 2.5 12 2.5 12s3.5 6 9.5 6 9.5-6 9.5-6"/></svg></button></div></label><label v-if="databaseType==='redis'">Key 筛选<input v-model.trim="databaseConnection.key_pattern" placeholder="* 或 user:*"></label></div>
          <div class="database-connection-actions"><span>密码只保留在当前页面会话中</span><button class="primary" :disabled="databaseTesting" @click="testDatabase">{{databaseTesting?'连接中…':'连接数据库'}}</button></div>
        </template>
      </div>

      <div class="database-client">
        <aside class="database-navigator">
          <div class="database-navigator-head"><div><span class="database-status-dot" :class="{online:databaseConnected}"></span><b>{{databaseType==='redis'?'键空间':'对象浏览器'}}</b></div><button :disabled="!databaseConnected" title="刷新对象" @click="testDatabase">↻</button></div>
          <div class="database-object-search"><span>⌕</span><input v-model="databaseObjectQuery" :placeholder="databaseType==='redis'?'筛选键…':'筛选数据表…'"></div>
          <div class="database-object-list">
            <button v-for="item in filteredDatabaseTables" :key="item.name" :class="{active:databaseSelectedTable===item.name}" @click="selectDatabaseObject(item.name)"><span>{{databaseType==='redis'?'K':'▦'}}</span><b>{{item.name}}</b></button>
            <div v-if="!databaseConnected" class="database-object-empty">连接数据库后浏览对象</div><div v-else-if="!filteredDatabaseTables.length" class="database-object-empty">{{databaseObjectQuery?'没有匹配项':databaseType==='redis'?'当前没有键':'当前没有数据表'}}</div>
          </div>
          <div class="database-navigator-foot">{{databaseTables.length}} {{databaseType==='redis'?'keys':'tables'}}</div>
        </aside>

        <section class="database-client-main">
          <div class="database-tabbar"><button :class="{active:databaseClientTab==='data'}" @click="databaseClientTab='data'">数据</button><button :class="{active:databaseClientTab==='structure'}" :disabled="!databaseSelectedTable" @click="databaseClientTab='structure'">结构</button><button :class="{active:databaseClientTab==='export'}" @click="databaseClientTab='export'">导出</button><button :class="{active:databaseClientTab==='import'}" @click="databaseClientTab='import'">导入</button><span></span><small v-if="databaseSelectedTable">{{databaseSelectedTable}}</small></div>

          <div v-if="databaseClientTab==='data'" class="database-client-pane">
            <div class="database-grid-toolbar"><div><button class="database-add-row" :disabled="!databaseConnected||(databaseType!=='redis'&&!databaseSelectedTable)" @click="startDatabaseAdd">＋ 新增{{databaseType==='redis'?'键':'行'}}</button><button :disabled="!databaseSelectedTable||databaseLoading" @click="loadDatabaseTable">↻ 刷新</button></div><div v-if="databaseSelectedTable" class="database-pagination"><span>共 {{databaseTotal}} 条</span><button :disabled="databasePage===0||databaseLoading" @click="changeDatabasePage(-1)">‹</button><b>{{databasePage+1}} / {{databasePageCount}}</b><button :disabled="databasePage+1>=databasePageCount||databaseLoading" @click="changeDatabasePage(1)">›</button></div></div>
            <div v-if="databaseLoading" class="database-client-empty">正在读取数据…</div>
            <div v-else-if="!databaseSelectedTable&&databaseType!=='redis'" class="database-client-empty"><div class="database-empty-icon"><AiIcon name="data" /></div><b>选择一张数据表</b><p>从左侧对象浏览器打开表，即可查看和直接编辑记录。</p></div>
            <div v-else class="database-editor-wrap">
              <table class="database-editor-table"><thead><tr><th class="database-row-index">#</th><th v-for="column in databaseDisplayColumns" :key="column.name"><b>{{column.name}}</b><small>{{column.type||'value'}}</small></th><th class="database-actions-column">操作</th></tr></thead><tbody>
                <tr v-if="databaseAddingRow" class="database-editing-row"><td class="database-row-index">新</td><td v-for="column in databaseDisplayColumns" :key="column.name"><input v-model="databaseNewValues[column.name]" :disabled="/blob|bytea/i.test(column.type||'')" :placeholder="/blob|bytea/i.test(column.type||'')?'二进制字段只读':column.primary_key?'自动生成或输入':'输入 '+column.name"></td><td class="database-row-actions"><button class="save" :disabled="databaseCrudSubmitting" @click="saveDatabaseNew">保存</button><button @click="databaseAddingRow=false">取消</button></td></tr>
                <tr v-for="(row,index) in databaseRows" :key="index"><td class="database-row-index">{{index+1}}</td><td v-for="column in databaseDisplayColumns" :key="column.name"><input v-if="databaseEditingRow===index" v-model="databaseEditValues[column.name]" :disabled="/blob|bytea/i.test(column.type||'')" :title="/blob|bytea/i.test(column.type||'')?'为避免破坏数据，二进制字段不支持直接编辑':''"><span v-else-if="row[column.name]===null||row[column.name]===undefined" class="database-null">NULL</span><span v-else class="database-cell-value" :title="databaseCellText(row[column.name])">{{databaseCellText(row[column.name])}}</span></td><td class="database-row-actions"><template v-if="databaseEditingRow===index"><button class="save" :disabled="databaseCrudSubmitting" @click="saveDatabaseEdit">保存</button><button @click="cancelDatabaseEdit">取消</button></template><template v-else><button @click="startDatabaseEdit(row,index)">编辑</button><button class="danger" @click="deleteDatabaseRow(row)">删除</button></template></td></tr>
                <tr v-if="!databaseRows.length&&!databaseAddingRow"><td :colspan="databaseDisplayColumns.length+2" class="database-table-empty">暂无记录，点击“新增{{databaseType==='redis'?'键':'行'}}”开始录入</td></tr>
              </tbody></table>
            </div>
          </div>

          <div v-else-if="databaseClientTab==='structure'" class="database-client-pane database-structure-pane"><div class="database-pane-heading"><div><b>{{databaseSelectedTable}}</b><span>字段结构</span></div><small>{{databaseColumns.length}} 个字段</small></div><div class="database-editor-wrap"><table class="database-structure-table"><thead><tr><th>字段名</th><th>数据类型</th><th>主键</th><th>允许 NULL</th></tr></thead><tbody><tr v-for="column in databaseColumns" :key="column.name"><td><b>{{column.name}}</b></td><td><code>{{column.type||'—'}}</code></td><td><span :class="['database-boolean',column.primary_key?'yes':'']">{{column.primary_key?'是':'否'}}</span></td><td><span :class="['database-boolean',column.nullable?'yes':'']">{{column.nullable?'是':'否'}}</span></td></tr></tbody></table></div></div>

          <div v-else class="database-client-pane database-transfer-pane">
            <div class="database-transfer-header">
              <div><span class="eyebrow">{{databaseClientTab==='export'?'DATABASE EXPORT':'DATABASE IMPORT'}}</span><b>{{databaseClientTab==='export'?'导出数据库备份':'导入数据库备份'}}</b><p>{{databaseClientTab==='export'?'选择数据范围并创建可迁移的完整备份。':'选择备份文件并恢复到当前数据库连接。'}}</p></div>
              <span class="database-transfer-format">ZIP · JSON</span>
            </div>

            <div v-if="databaseClientTab==='export'" class="database-transfer-body">
              <section class="database-transfer-form">
                <div class="database-transfer-section-title"><span>01</span><div><b>选择导出范围</b><small>当前连接 · {{databaseType.toUpperCase()}}</small></div></div>
                <div class="database-scope-bar"><span>导出范围</span><div><button :class="{active:databaseExportAll}" @click="databaseExportAll=true">全部{{databaseType==='redis'?'键':'表'}} <b>{{databaseTables.length}}</b></button><button :class="{active:!databaseExportAll}" @click="databaseExportAll=false">指定{{databaseType==='redis'?'键':'表'}} <b>{{databaseExportTables.length}}</b></button></div></div>
                <div v-if="!databaseExportAll" class="database-transfer-objects"><div class="database-transfer-objects-head"><div><b>选择{{databaseType==='redis'?'键':'数据表'}}</b><small>已选择 {{databaseExportTables.length}} / {{databaseTables.length}}</small></div><div><button @click="databaseExportTables=databaseTables.map(item=>item.name)">全选</button><button @click="databaseExportTables=[]">清空</button></div></div><div class="database-transfer-object-scroll"><label v-for="item in databaseTables" :key="item.name"><input v-model="databaseExportTables" type="checkbox" :value="item.name"><i></i><span>{{item.name}}</span></label><div v-if="!databaseTables.length" class="database-transfer-no-objects">连接数据库后选择对象</div></div></div>
                <div class="database-transfer-summary"><span>02</span><div><b>输出格式</b><p>ZIP 压缩包 · JSON 数据与字段结构 · 全量记录</p></div><strong>ZIP</strong></div>
                <div class="database-transfer-submit"><div><b>{{databaseExportAll?'导出完整数据库':`导出 ${databaseExportTables.length} 个对象`}}</b><small>任务将在后台运行，可在下方任务列表查看进度。</small></div><button :disabled="databaseTaskSubmitting||!databaseConnected||(!databaseExportAll&&!databaseExportTables.length)" @click="createDatabaseExport">{{databaseTaskSubmitting?'正在创建…':'开始导出'}} <span>→</span></button></div>
              </section>
              <aside class="database-transfer-guide"><span class="database-transfer-guide-icon">↑</span><b>完整备份</b><p>保存字段结构和全部记录，适合数据库归档或迁移到另一个实例。</p><ul><li><i>1</i><span>读取对象结构</span></li><li><i>2</i><span>导出全部数据</span></li><li><i>3</i><span>生成 ZIP 结果</span></li></ul><small>导出操作不会修改当前数据库。</small></aside>
            </div>

            <div v-else class="database-transfer-body">
              <section class="database-transfer-form">
                <div class="database-transfer-section-title"><span>01</span><div><b>选择备份文件</b><small>支持本工具生成的 ZIP 或 JSON</small></div></div>
                <label class="database-import-dropzone"><input ref="databaseImportInput" type="file" accept=".zip,.json" @change="chooseDatabaseImport"><span class="database-import-icon">＋</span><div><b>{{databaseImportFile?'更换备份文件':'选择备份文件'}}</b><small>点击浏览本地 ZIP / JSON 文件</small></div></label>
                <div v-if="databaseImportFile" class="database-import-file"><span>JSON</span><div><b>{{databaseImportFile.name}}</b><small>{{formatBytes(databaseImportFile.size)}}</small></div><button @click="databaseImportFile=null;databaseImportInput.value=''">移除</button></div>
                <div class="database-import-policy"><div><span>02</span><div><b>同名数据处理</b><small>控制目标库已存在对象的处理方式</small></div></div><label><input v-model="databaseOverwrite" type="checkbox"><i></i><span><b>覆盖已有数据</b><small>{{databaseOverwrite?'清空同名表后恢复备份':'保留现有内容并追加记录'}}</small></span></label></div>
                <div class="database-transfer-submit"><div><b>恢复到当前 {{databaseType.toUpperCase()}} 连接</b><small>{{databaseImportFile?databaseImportFile.name:'请先选择备份文件'}}</small></div><button :disabled="databaseTaskSubmitting||!databaseImportFile||!databaseConnected" @click="createDatabaseImport">{{databaseTaskSubmitting?'正在创建…':'开始导入'}} <span>→</span></button></div>
              </section>
              <aside class="database-transfer-guide import"><span class="database-transfer-guide-icon">↓</span><b>恢复备份</b><p>根据备份重建对象并写入数据。正式操作前建议先导出当前数据库。</p><ul><li><i>1</i><span>校验备份文件</span></li><li><i>2</i><span>创建或匹配对象</span></li><li><i>3</i><span>批量写入记录</span></li></ul><small>开启覆盖后，同名表中的现有数据会被清空。</small></aside>
            </div>
          </div>
        </section>
      </div>
      </div>
      <section class="queue database-queue"><div class="queue-head"><div><span class="eyebrow">DATABASE TASK QUEUE</span><h2>迁移任务</h2></div><button class="refresh" @click="loadDatabaseTasks">刷新</button></div><div v-if="!databaseTasks.length" class="empty">暂无数据库导入导出任务。</div><article v-for="task in databaseTasks" :key="task.id" class="task database-task"><div class="task-main"><div class="task-icon"><AiIcon name="data" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.mode==='export'?'导出':'导入'}} · {{task.request?.type?.toUpperCase()}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><a v-if="task.mode==='export'&&task.status==='completed'" :href="`/api/database/tasks/${task.id}/export`">下载 ZIP</a><button v-if="task.status==='failed'" class="retry" @click="retryDatabaseTask(task)">重试</button><button class="danger" @click="deleteDatabaseTask(task)">删除</button></div></article></section>
    </section>
    <section v-if="view==='md-word'" class="md-word-page">
      <header><div><span class="eyebrow">MARKDOWN TO WORD</span><h1>Markdown 转 Word</h1><p>将 Markdown 转换为排版精良的 Word 文档，Mermaid 图形自动生成高清图片并嵌入。</p></div></header>
      <div class="md-word-workspace">
        <aside class="panel md-word-config"><div class="panel-title"><b>转换配置</b><span>DOCX</span></div><label>Markdown 文件<input ref="mdWordInput" type="file" accept=".md,.markdown,text/markdown" @change="chooseMdWord"></label><div class="file-summary">{{mdWordFile?`已选择 ${mdWordFile.name}`:'请选择 UTF-8 编码的 .md 或 .markdown 文件'}}</div><label>文档标题（可选）<input v-model.trim="mdWordTitle" maxlength="120" placeholder="默认使用文件名"></label><label>Mermaid 图形主题<select v-model="mdWordMermaidTheme"><option value="neutral">商务黑 · 默认</option><option value="default">清晰蓝紫</option><option value="forest">森林绿</option></select></label><label class="check-label md-word-toc"><input v-model="mdWordToc" type="checkbox">生成三级目录</label><div class="hint">基于 Pandoc 转换，支持 GFM 表格、任务列表和代码高亮。Mermaid 默认使用商务黑主题，生成 3 倍分辨率透明 PNG；图片在 Word 中自动等比缩放并居中。</div><button class="primary md-word-submit" :disabled="mdWordSubmitting||!mdWordFile" @click="submitMdWord">{{mdWordSubmitting?'正在上传…':'创建转换任务'}}</button></aside>
        <div class="md-word-preview"><template v-if="mdWordPreviewTask"><div class="pdf-preview-head"><div><b>{{mdWordPreviewTask.result?.docx}}</b><small>{{mdWordPreviewTask.result?.mermaid_count||0}} 张 Mermaid 图 · Word 页面预览</small></div><button @click="mdWordPreviewTask=null">关闭预览</button></div><iframe :key="mdWordPreviewNonce" class="pdf-preview-frame" :src="`/api/md-word/tasks/${mdWordPreviewTask.id}/preview#page=1`"></iframe></template><div v-else class="pdf-help-empty"><div class="md-word-empty-icon"><AiIcon name="word" /></div><b>Word 结果预览</b><p>转换完成后点击任务中的“预览”，这里将展示与 Word 对应的页面效果。</p></div></div>
      </div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">DOCUMENT TASK QUEUE</span><h2>转换任务</h2></div><button class="refresh" @click="loadMdWordTasks">刷新</button></div><div v-if="!mdWordTasks.length" class="empty">暂无 Markdown 转 Word 任务。</div><article v-for="task in mdWordTasks" :key="task.id" class="task md-word-task"><div class="task-main"><div class="task-icon"><AiIcon name="word" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.options?.toc?'含目录':'无目录'}} · {{mermaidThemeName(task.options?.mermaid_theme)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions md-word-actions"><template v-if="task.status==='completed'"><button @click="previewMdWord(task)">预览</button><a :href="`/api/md-word/tasks/${task.id}/export`">下载 Word</a></template><button v-if="task.status==='failed'" class="retry" @click="retryMdWord(task)">重新转换</button><button class="danger" @click="deleteMdWord(task)">删除</button></div></article></section>
    </section>
    <section v-if="view==='pdf'" class="pdf-page"><header><div><span class="eyebrow">WEB TO PDF</span><h1>网页转 PDF</h1><p>输入网址或上传 Excel，批量生成网页 PDF 快照。</p></div></header><div class="pdf-workspace"><aside class="panel"><label>网址（每行一个）<textarea v-model="pdfUrls" rows="7" placeholder="https://example.com"></textarea></label><label>或上传 Excel<input ref="pdfInput" type="file" accept=".xlsx,.xls" @change="choosePdf"></label><label>结果文件命名模板<input v-model.trim="pdfFilenameTemplate" maxlength="160" placeholder="{index}_{host}"></label><div class="filename-template-help"><span>可用变量</span><code>{index}</code><code>{host}</code><code>{title}</code></div><div class="hint">Excel 默认读取第一列网址；文件名示例：001_example.com.pdf。网页标题可用 {title} 变量。</div><button class="primary pdf-submit" :disabled="pdfUploading" @click="submitPdf">{{pdfUploading?'提交中…':'创建转换任务'}}</button></aside><div class="pdf-help"><template v-if="pdfPreviewFile"><div class="pdf-preview-head"><b>{{pdfPreviewFile.name}}</b><button @click="pdfPreviewFile=null">关闭预览</button></div><iframe :key="pdfPreviewNonce" class="pdf-preview-frame" :src="`/api/pdf/tasks/${pdfDetailTask.id}/preview/${encodeURIComponent(pdfPreviewFile.name)}#page=1`"></iframe></template><div v-else class="pdf-help-empty"><b>PDF 预览</b><p>在下方任务中点击“查看结果”，再选择文件预览。</p></div></div></div><section class="queue"><div class="queue-head"><div><span class="eyebrow">PDF TASK QUEUE</span><h2>转换任务</h2></div><button class="refresh" @click="loadPdfTasks">刷新</button></div><div v-if="!pdfTasks.length" class="empty">暂无网页转 PDF 任务。</div><article v-for="task in pdfTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="file" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.current}}/{{task.total}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions pdf-task-actions"><template v-if="task.status==='completed'"><button class="pdf-result-btn" @click="openPdfDetails(task)">查看结果 <span>{{task.result?.files?.length||0}}</span></button><a :href="`/api/pdf/tasks/${task.id}/export`">下载 ZIP</a></template><button v-if="task.status==='failed'" class="retry" @click="retryPdf(task)">重新转换</button><button class="danger" @click="deletePdf(task)">删除</button></div><div v-if="pdfDetailTask?.id===task.id" class="pdf-inline-list"><div class="pdf-inline-head"><div><b>转换结果</b><small>{{pdfDetailFiles.length}} / {{task.result?.files?.length||0}} 个文件</small></div><input v-model.trim="pdfFileQuery" type="search" placeholder="搜索文件名或网址"></div><div class="pdf-inline-scroll"><div v-if="!pdfDetailFiles.length" class="pdf-inline-empty">没有匹配的文件</div><div v-for="file in pdfDetailFiles" :key="file.name" class="pdf-inline-row"><div><span>{{file.name}}</span><small>{{file.url}}</small></div><button @click="previewPdfFile(file)">预览</button></div></div></div></article></section></section>
    <section v-if="view==='trending'" class="trending-page">
      <header><div><span class="eyebrow">GITHUB DAILY TRENDING</span><h1>GitHub 每日热门报告</h1><p>汇总当天热门开源仓库，历史报告最多保留近 7 天。</p></div><div class="trending-header-actions"><div class="language-switch"><button :class="{active:trendingLanguage==='zh'}" @click="trendingLanguage='zh'">中文</button><button :class="{active:trendingLanguage==='en'}" @click="trendingLanguage='en'">English</button></div><button class="refresh trending-refresh" :disabled="trendingRefreshing" @click="refreshTrending">{{trendingRefreshing?'正在生成…':'刷新今日报告'}}</button></div></header>
      <div class="trending-view-tabs"><button :class="{active:trendingView==='report'}" @click="trendingView='report'">每日报告</button><button :class="{active:trendingView==='favorites'}" @click="trendingView='favorites'">我的收藏 <b>{{trendingFavorites.length}}</b></button></div>
      <template v-if="trendingView==='report'">
        <div class="report-date-tabs"><button v-for="item in trendingDates" :key="item.date" :class="{active:trendingReport?.date===item.date}" @click="loadTrendingReport(item.date)"><b>{{item.date}}</b><small>{{item.repository_count}} 个仓库</small></button></div>
        <div v-if="trendingLoading&&!trendingReport" class="empty">正在加载 GitHub 热门报告…</div><div v-else-if="!trendingReport" class="empty">暂无报告，请点击刷新今日报告。</div>
        <template v-else><div class="report-summary"><div><span>DAILY REPORT</span><h2>{{trendingReport.title}}</h2><p>生成于 {{dateText(trendingReport.generated_at)}} · {{trendingReport.translation?.status==='fallback'?'部分简介翻译失败，已显示原文':'简介已提供中文翻译'}}</p></div><strong>{{trendingReport.repository_count}}<small>热门仓库</small></strong></div><div class="repo-grid"><article v-for="repo in trendingReport.repositories" :key="repo.full_name" class="repo-card"><div class="repo-rank">#{{repo.rank}}</div><div class="repo-title"><div><small>{{repo.full_name.split('/')[0]}}</small><h3>{{repo.name}}</h3></div><div class="repo-card-actions"><button :class="{active:trendingFavoriteNames.has(repo.full_name)}" @click="toggleTrendingFavorite(repo)">{{trendingFavoriteNames.has(repo.full_name)?'★ 已收藏':'☆ 收藏'}}</button><a :href="repo.url" target="_blank" rel="noopener noreferrer">打开 GitHub ↗</a></div></div><p>{{trendingLanguage==='zh'?(repo.description_zh||repo.description):repo.description}}</p><small v-if="trendingLanguage==='zh'&&repo.description_zh&&repo.description_zh!==repo.description" class="repo-original">{{repo.description}}</small><div class="repo-meta"><span><i :style="{background:repo.language==='未标注'?'#aaa':'#b76542'}"></i>{{repo.language}}</span><span>★ {{repo.stars}}</span><span>⑂ {{repo.forks}}</span><b>今日 +{{repo.stars_today}}</b></div></article></div></template>
      </template>
      <template v-else><div v-if="!trendingFavorites.length" class="empty">暂无收藏，可在每日报告中收藏常用仓库。</div><div v-else class="favorites-head"><div><b>收藏列表</b><small>收藏不会随七天历史报告清理</small></div><span>{{trendingFavorites.length}} 个仓库</span></div><div class="repo-grid favorite-grid"><article v-for="repo in trendingFavorites" :key="repo.full_name" class="repo-card favorite-card"><div class="repo-title"><div><small>{{repo.full_name.split('/')[0]}}</small><h3>{{repo.name}}</h3></div><div class="repo-card-actions"><button class="active" @click="toggleTrendingFavorite(repo)">★ 取消收藏</button><a :href="repo.url" target="_blank" rel="noopener noreferrer">打开 GitHub ↗</a></div></div><p>{{trendingLanguage==='zh'?(repo.description_zh||repo.description):repo.description}}</p><div class="repo-meta"><span><i :style="{background:repo.language==='未标注'?'#aaa':'#b76542'}"></i>{{repo.language}}</span><span>★ {{repo.stars}}</span><span>收藏于 {{dateText(repo.favorited_at)}}</span></div></article></div></template>
    </section>
    <section v-if="view==='nebula'" class="es-page nebula-page">
      <header><div><span class="eyebrow">NEBULAGRAPH MIGRATION</span><h1>NebulaGraph 数据导入导出</h1><p>迁移 NebulaGraph 3.x 的 Space Schema、Tag、Edge、点和边数据。</p></div></header>
      <div class="es-connection panel"><div class="panel-title"><b>连接配置</b><span v-if="nebulaSpaces.length" class="connected">已连接</span></div><div class="nebula-grid"><label>Graph 地址<input v-model.trim="nebulaConnection.host" placeholder="127.0.0.1"></label><label>端口<input v-model.number="nebulaConnection.port" type="number" min="1" max="65535"></label><label>用户名<input v-model.trim="nebulaConnection.username"></label><label>密码<div class="password-field"><input v-model="nebulaConnection.password" :type="showNebulaPassword?'text':'password'"><button type="button" :aria-label="showNebulaPassword?'隐藏密码':'显示密码'" @click="showNebulaPassword=!showNebulaPassword"><svg v-if="showNebulaPassword" viewBox="0 0 24 24"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.8"/></svg><svg v-else viewBox="0 0 24 24"><path d="m3 3 18 18M10.6 6.2A10.5 10.5 0 0 1 12 6c6 0 9.5 6 9.5 6a15 15 0 0 1-2.1 2.8M6.2 6.2C3.8 8 2.5 12 2.5 12s3.5 6 9.5 6a9 9 0 0 0 3-.5M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div></label></div><button class="primary es-connect" :disabled="nebulaConnecting" @click="connectNebula">{{nebulaConnecting?'连接中…':'测试连接并获取 Space'}}</button></div>
      <div class="es-workspace"><aside class="panel"><div class="segmented"><button :class="{active:nebulaMode==='export'}" @click="nebulaMode='export'">导出备份</button><button :class="{active:nebulaMode==='import'}" @click="nebulaMode='import'">导入恢复</button></div><template v-if="nebulaMode==='export'"><div class="index-head"><b>选择 Space</b><button @click="selectedSpaces=selectedSpaces.length===nebulaSpaces.length?[]:[...nebulaSpaces]">{{selectedSpaces.length===nebulaSpaces.length&&nebulaSpaces.length?'取消全选':'全选'}}</button></div><div class="index-list"><label v-for="space in nebulaSpaces" :key="space" class="index-item space-item"><input type="checkbox" v-model="selectedSpaces" :value="space"><span>{{space}}</span></label><p v-if="!nebulaSpaces.length" class="muted">请先测试连接获取 Space</p></div><div class="hint">导出所选 Space 的完整 Schema、全部点和全部边。</div></template><template v-else><label>选择导出 ZIP<input ref="nebulaZipInput" class="folder-input" type="file" accept=".zip" @change="chooseNebulaFiles"></label><label>或选择备份目录<input ref="nebulaDirInput" class="folder-input" type="file" webkitdirectory directory multiple accept=".txt,.csv" @change="chooseNebulaFiles"></label><div class="file-summary">{{nebulaFiles.length?`已选择 ${nebulaFiles.length} 个文件`:'请选择一种导入方式'}}</div><div class="hint">完整导入备份中的 Space、Tag、Edge、点和边。</div></template><button class="primary es-submit" :disabled="nebulaSubmitting" @click="submitNebula">{{nebulaSubmitting?'提交中…':nebulaMode==='export'?'创建导出任务':'上传并创建导入任务'}}</button></aside><div class="es-help nebula-help"><b>{{nebulaMode==='export'?'备份结构':'恢复顺序'}}</b><pre v-if="nebulaMode==='export'">{{'space/\n├── space_base.txt\n├── space_node.csv\n└── space_edge.csv'}}</pre><p v-else>依次创建 Space、Tag 和 Edge Schema，等待元数据生效后，再导入全部点和边。</p><p>密码只用于当前任务，不写入任务状态。</p></div></div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">NEBULA TASK QUEUE</span><h2>迁移任务</h2></div><button class="refresh" @click="loadNebulaTasks">刷新</button></div><div v-if="!nebulaTasks.length" class="empty">暂无 NebulaGraph 任务。</div><article v-for="task in nebulaTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="graph" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.mode==='export'?'导出':'导入'}} · {{task.id.slice(0,8)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><a v-if="task.mode==='export'&&task.status==='completed'" :href="`/api/nebula/tasks/${task.id}/export`">导出 ZIP</a><button class="danger" @click="deleteNebula(task)">删除</button></div></article></section>
    </section>
    <section v-if="view==='es'" class="es-page">
      <header><div><span class="eyebrow">ELASTICSEARCH OPERATIONS</span><h1>ES 数据导入导出</h1><p>连接 Elasticsearch 7/8，管理索引备份和恢复任务。</p></div></header>
      <div class="es-connection panel"><div class="panel-title"><b>连接配置</b><span v-if="esInfo" class="connected">已连接 {{esInfo.version||''}}</span></div><div class="es-grid"><label>ES 地址<input v-model.trim="esConnection.host" placeholder="http://127.0.0.1:9200"></label><label>用户名<input v-model.trim="esConnection.username" autocomplete="off"></label><label>密码<div class="password-field"><input v-model="esConnection.password" :type="showEsPassword?'text':'password'" autocomplete="new-password"><button type="button" :aria-label="showEsPassword?'隐藏密码':'显示密码'" @click="showEsPassword=!showEsPassword"><svg v-if="showEsPassword" viewBox="0 0 24 24"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.8"/></svg><svg v-else viewBox="0 0 24 24"><path d="m3 3 18 18M10.6 6.2A10.5 10.5 0 0 1 12 6c6 0 9.5 6 9.5 6a15 15 0 0 1-2.1 2.8M6.2 6.2C3.8 8 2.5 12 2.5 12s3.5 6 9.5 6a9 9 0 0 0 3-.5M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div></label><label class="check-label"><input v-model="esConnection.verify_certs" type="checkbox">验证 HTTPS 证书</label></div><button class="primary es-connect" :disabled="esConnecting" @click="connectEs">{{esConnecting?'连接中…':'测试连接并获取索引'}}</button></div>
      <div class="es-workspace"><aside class="panel"><div class="segmented"><button :class="{active:esMode==='export'}" @click="esMode='export'">导出备份</button><button :class="{active:esMode==='import'}" @click="esMode='import'">导入恢复</button></div><template v-if="esMode==='export'"><div class="index-head"><b>选择索引</b><button @click="toggleAllIndexes">{{selectedIndexes.length===esIndexes.length&&esIndexes.length?'取消全选':'全选'}}</button></div><div class="index-list"><label v-for="item in esIndexes" :key="item.index" class="index-item"><input type="checkbox" v-model="selectedIndexes" :value="item.index"><span>{{item.index}}</span><small>{{item['docs.count']||0}} docs · {{item['store.size']||'—'}}</small></label><p v-if="!esIndexes.length" class="muted">请先测试连接获取索引</p></div><div class="hint">将导出所选索引的完整 Mapping 和全部文档。</div></template><template v-else><label>选择导出 ZIP<input ref="esZipInput" class="folder-input" type="file" accept=".zip" @change="chooseEsFiles"></label><label>或选择 mapping/data 目录<input ref="esDirInput" class="folder-input" type="file" webkitdirectory directory multiple accept=".json" @change="chooseEsFiles"></label><div class="file-summary">{{esFiles.length?`已选择 ${esFiles.length} 个文件`:'请选择一种导入方式'}}</div><label class="check-label"><input v-model="esOptions.overwrite" type="checkbox">覆盖已存在索引</label><div class="hint">将完整导入文件中的全部索引文档，不截断数据。</div></template><button class="primary es-submit" :disabled="esSubmitting" @click="submitEs">{{esSubmitting?'提交中…':esMode==='export'?'创建导出任务':'上传并创建导入任务'}}</button></aside><div class="es-help"><b>{{esMode==='export'?'导出结构':'导入说明'}}</b><pre v-if="esMode==='export'">{{'es-export/\n├── mapping/\n│   └── index_mapping.json\n└── data/\n    └── index.json'}}</pre><p v-else>支持本工具生成的 ZIP，或包含 mapping/ 与 data/ 子目录的文件夹。数据文件按 JSON Lines 读取，每行一个文档。</p><p>密码只用于本次请求，不保存到任务记录。</p></div></div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">ES TASK QUEUE</span><h2>数据任务</h2></div><button class="refresh" @click="loadEsTasks">刷新</button></div><div v-if="!esTasks.length" class="empty">暂无 ES 数据任务。</div><article v-for="task in esTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="data" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.mode==='export'?'导出':'导入'}} · {{task.id.slice(0,8)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><button v-if="task.status==='running'||task.status==='queued'" @click="controlEs(task,'pause')">暂停</button><button v-if="task.status==='paused'" class="resume" @click="controlEs(task,'resume')">继续</button><a v-if="task.mode==='export'&&task.status==='completed'" :href="`/api/es/tasks/${task.id}/export`">导出 ZIP</a><button class="danger" @click="controlEs(task,'delete')">删除</button></div></article></section>
    </section>
    <section v-if="view==='docker'" class="docker-page">
      <header><div><span class="eyebrow">OFFLINE DELIVERY</span><h1>Docker 离线包下载</h1><p>选择目标 Linux 架构及版本，制作可迁移的离线安装包。</p></div></header>
      <div class="docker-workspace"><aside class="panel"><div class="panel-title"><b>下载配置</b><span>Linux</span></div><label>目标架构<select v-model="dockerForm.arch" @change="dockerForm.docker_version='';loadVersions()"><option value="x86_64">x86_64 · Intel/AMD 64 位</option><option value="aarch64">aarch64 · ARM 64 位</option><option value="armv7l">armv7l · ARM 32 位</option></select></label><label>Docker 版本<select v-model="dockerForm.docker_version" :disabled="versionsLoading"><option value="">自动选择最新版</option><option v-for="v in compatibleDockerVersions" :key="v" :value="v">{{v}}</option></select></label><label>Docker Compose 版本<select v-model="dockerForm.compose_version" :disabled="versionsLoading"><option value="">自动选择最新版</option><option v-for="v in versions.compose.filter(x=>Number(x.split('.')[0])>=2)" :key="v" :value="v">{{v}}</option></select></label><p v-if="compatibilityError" class="compat-error">{{compatibilityError}}</p><button class="version-btn" @click="loadVersions">{{versionsLoading?'正在获取…':'刷新可用版本'}}</button><div class="hint">当前工具使用 Compose V2，Docker Engine 必须为 20.10 或更高版本。两者没有严格的一一对应关系，新版本通过 Docker API 自动协商。</div><button class="primary docker-submit" :disabled="dockerSubmitting||!!compatibilityError" @click="submitDocker">{{dockerSubmitting?'提交中…':'创建离线包任务'}}</button></aside><div class="terminal-art"><span>PACKAGE BLUEPRINT</span><pre>{{packageTree}}</pre><p>适用于无法直接访问互联网的 Linux 服务器交付场景。</p></div></div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">PACKAGE QUEUE</span><h2>制作任务</h2></div><button class="refresh" @click="loadDockerTasks">刷新</button></div><div v-if="!dockerTasks.length" class="empty">暂无离线包任务。</div><article v-for="task in dockerTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="package" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.id.slice(0,8)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><button v-if="task.status==='running'" @click="controlDocker(task,'pause')">暂停</button><button v-if="task.status==='paused'" class="resume" @click="controlDocker(task,'resume')">继续</button><button v-if="task.status==='failed'" class="retry" @click="controlDocker(task,'retry')">重试</button><a v-if="task.status==='completed'" :href="`/api/docker/tasks/${task.id}/export`">导出</a><button class="danger" @click="controlDocker(task,'delete')">删除</button></div></article></section>
    </section>
    <section v-if="view==='shp'" class="shp-page">
      <header><div><span class="eyebrow">SHAPEFILE VIEWER</span><h1>SHP 文件预览</h1><p>多次追加上传一个或多个 Shapefile 文件组，在卫星地图中对齐叠加预览。</p></div></header>
      <div class="shp-workspace"><aside class="panel"><div class="panel-title"><b>图层文件</b><span>{{shpLayers.length}} 个图层</span></div><label>选择 SHP 文件组<input ref="shpInput" class="folder-input" type="file" multiple accept=".shp,.shx,.dbf,.prj,.cpg" @change="chooseShpFiles"></label><div class="file-summary">{{shpFiles.length?`已识别 ${selectedShpGroupCount} 个 SHP 图层`:'请选择同名的 SHP、SHX、DBF、PRJ 文件，CPG 可选'}}</div><button class="primary shp-upload" :disabled="shpUploading||!selectedShpGroupCount" @click="uploadShp">{{shpUploading?'正在解析…':'上传并添加图层'}}</button><div class="shp-layer-list"><div v-if="!shpLayers.length" class="shp-empty">尚未添加图层</div><article v-for="item in shpLayers" :key="item.id"><button class="visibility" :class="{off:!item.visible}" :aria-label="item.visible?'隐藏图层':'显示图层'" @click="toggleShp(item)">{{item.visible?'●':'○'}}</button><div><b>{{item.name}}</b><small>{{item.shape_type}} · {{item.feature_count}} 个要素</small><small>{{item.crs}}</small></div><div class="shp-actions"><button @click="locateShp(item)">定位</button><button class="danger" @click="deleteShp(item)">删除</button></div></article></div></aside><div ref="shpMapEl" class="shp-map"></div></div>
    </section>
    <section v-if="view==='gjb'" class="gjb-page">
      <header><div><span class="eyebrow">GJB5068 CONVERTER</span><h1>GJB 地图转 Shapefile</h1><p>上传完整 GJB 图幅目录，解析多图层组的点、线、面和注记并生成标准 GIS 文件。</p></div></header>
      <div class="gjb-workspace"><aside class="panel"><div class="panel-title"><b>转换配置</b><span>GJB5068-2004</span></div><label>GJB 图幅目录<input ref="gjbInput" class="folder-input" type="file" webkitdirectory directory multiple @change="chooseGjbFiles"></label><div class="file-summary">{{gjbFiles.length?`已选择 ${gjbFiles.length} 个文件`:'请选择包含 SMS 及 XMS、XSX、XTP、XZB 图层组的目录'}}</div><label>输出坐标系<select v-model="gjbForm.crs" disabled><option value="auto">根据 SMS 自动识别</option></select></label><div class="hint">支持 A/B/C/D/E/F/I/J/K/L/R 图层组和 P/L/A/N 几何。将应用 SMS 相对原点与坐标放大系数，并按点、线、面、注记各输出一份合并 Shapefile。</div><button class="primary docker-submit" :disabled="gjbSubmitting||!gjbFiles.length" @click="submitGjb">{{gjbSubmitting?'正在上传…':'上传并开始转换'}}</button></aside><div class="gjb-preview"><div v-if="!previewTask" class="preview-empty"><b>转换结果预览</b><p>转换完成后自动预览合并后的点、线、面和注记。</p></div><template v-else><div class="preview-head"><b>{{previewTask.name}}</b><span>{{previewTask.result?.feature_count}} 个要素 · {{previewTask.result?.crs}}</span></div><div ref="gjbMapEl" class="preview-map"></div></template></div></div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">CONVERSION QUEUE</span><h2>转换任务</h2></div><button class="refresh" @click="loadGjbTasks">刷新</button></div><div v-if="!gjbTasks.length" class="empty">暂无 GJB 转换任务。</div><article v-for="task in gjbTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="layers" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.request.crs || '自动坐标系'}} · {{task.id.slice(0,8)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><button v-if="task.status==='failed'" class="retry" @click="controlGjb(task,'retry')">重试</button><button v-if="task.status==='completed'" @click="previewGjb(task)">预览</button><a v-if="task.status==='completed'" :href="`/api/gjb/tasks/${task.id}/export`">下载</a><button class="danger" @click="controlGjb(task,'delete')">删除</button></div></article></section>
    </section>
    <section v-if="view==='propzone'" class="propzone-page">
      <header><div><span class="eyebrow">PROPZONE · USA DATASET</span><h1>全美行政区域 SHP 下载</h1><p>搜索或在地图中点选美国行政区域，获取 PropZone zoning 数据；无 zoning 记录时导出行政区边界。</p></div></header>
      <div class="propzone-workspace"><aside class="panel propzone-config">
        <div class="panel-title"><b>区域选择</b><span>{{propzoneSelected.length}} 个区域</span></div>
        <div class="propzone-level-picker"><span>下载颗粒度</span><div><button v-for="item in [{value:'all',label:'全部'},{value:'state',label:'州'},{value:'county',label:'County'},{value:'city',label:'城市'}]" :key="item.value" :class="{active:propzoneLevel===item.value}" @click="setPropzoneLevel(item.value)">{{item.label}}</button></div><small>区域目录会按颗粒度缓存到本地；州可直接加载全量，County/城市请输入关键词后离线复用。</small></div>
        <label>搜索{{propzoneLevelName(propzoneLevel)}}<div class="searchbox"><input v-model="propzoneQuery" :placeholder="propzoneLevel==='state'?'留空可加载全部州':propzoneLevel==='county'?'例如 Los Angeles County':'城市名称或粘贴 PropZone 官方 URL'" @keyup.enter="searchPropzone"><button @click="searchPropzone">{{propzoneSearching?'…':'搜索'}}</button></div></label>
        <div v-if="propzoneResults.length" class="propzone-results"><button v-for="area in propzoneResults" :key="area.id" @click="selectPropzoneResult(area)"><b>{{area.short_name}}</b><small>{{area.name}}</small><em>{{area.type}} · {{area.state?.toUpperCase()||'US'}}</em></button></div><div v-else-if="propzoneQuery.trim().length>=2&&!propzoneSearching" class="propzone-results-empty">没有匹配的行政区域；可尝试完整 County/城市名称，或粘贴 PropZone 官方路径。</div>
        <div class="propzone-selected"><div class="selected-head"><b>已选择区域</b><button v-if="propzoneSelected.length" @click="clearPropzone">清空</button></div><div v-if="!propzoneSelected.length" class="muted">搜索结果后点击地图或结果项加入</div><article v-for="area in propzoneSelected" :key="area.id" class="propzone-area-card"><div class="propzone-area-main"><div class="propzone-area-title"><input :checked="area.visible!==false" type="checkbox" @change="togglePropzoneArea(area,$event)"><b>{{area.short_name}}</b><small>{{area.state?.toUpperCase()}} · {{area.type}}</small><button v-if="area.type==='state'||String(area.name||'').toLowerCase().includes('state')" class="propzone-children-btn" @click="loadPropzoneChildren(area)">{{propzoneChildrenLoading[area.id]?'加载中…':area.children_loaded?'已加载下级':'加载下级'}}</button><button v-if="area.zones?.length||area.children?.length" type="button" class="propzone-details-toggle" :class="{collapsed:area.details_expanded===false}" :aria-label="area.details_expanded===false?'展开图层':'收起图层'" :title="area.details_expanded===false?'展开图层':'收起图层'" @click="area.details_expanded=area.details_expanded===false"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></button></div><div v-show="area.details_expanded!==false" class="propzone-area-details"><div v-if="area.children?.length" class="propzone-children-tree"><label v-for="child in area.children" :key="child.id"><input type="checkbox" :checked="propzoneSelected.some(item=>propzoneAreaKey(item)===propzoneAreaKey(child))" @change="togglePropzoneChild(child,$event)"><span>{{child.short_name}}</span></label></div><div v-if="area.zones?.length" class="propzone-zones"><div class="propzone-zones-head"><span>ZONE 图层</span><small>{{area.selected_zone_ids==null?area.zones.length:area.selected_zone_ids.length}} / {{area.zones.length}}</small></div><label v-for="zone in area.zones" :key="zone.properties?.zone_id"><input type="checkbox" :checked="area.selected_zone_ids==null||area.selected_zone_ids.includes(String(zone.properties?.zone_id||''))" @change="togglePropzoneZone(area,zone)"><i :style="{background:zone.properties?.color||'#4169e1'}"></i><span>{{zone.properties?.zone_code||'未命名区域'}}</span></label></div><div v-else class="propzone-no-zones">该区域暂无可用 ZONE 图层，将下载行政区边界。</div></div></div><button class="propzone-remove" @click="removePropzoneArea(area)">×</button></article></div>
        <div class="hint">可直接点击右侧卫星地图识别附近行政区域，也可使用搜索结果。下载内容优先使用 PropZone municipal zoning district 图层，并保留 zone_id、zone_code、color 字段。</div>
        <button class="primary propzone-submit" :disabled="propzoneSubmitting||!propzoneSelected.length" @click="submitPropzone">{{propzoneSubmitting?'提交中…':'创建 SHP 下载任务'}}</button>
      </aside><div ref="propzoneMapEl" class="propzone-map"></div></div>
      <section class="queue"><div class="queue-head"><div><span class="eyebrow">PROPZONE TASK QUEUE</span><h2>下载任务</h2></div><button class="refresh" @click="loadPropzoneTasks">刷新</button></div><div v-if="!propzoneTasks.length" class="empty">暂无全美行政区下载任务。</div><article v-for="task in propzoneTasks" :key="task.id" class="task"><div class="task-main"><div class="task-icon"><AiIcon name="layers" /></div><div><b>{{task.name}}</b><small>{{dateText(task.created_at)}} · {{task.current||0}}/{{task.total||0}} 个区域 · {{task.id.slice(0,8)}}</small></div></div><div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div><span class="badge" :class="task.status">{{statusText(task.status)}}</span><div class="task-actions"><button v-if="task.status==='queued'||task.status==='running'" @click="controlPropzone(task,'pause')">暂停</button><button v-if="task.status==='paused'" class="resume" @click="controlPropzone(task,'resume')">继续</button><button v-if="task.status==='failed'" class="retry" @click="controlPropzone(task,'retry')">重试</button><a v-if="task.status==='completed'" class="export" :href="`/api/propzone/tasks/${task.id}/export`">下载 SHP</a><button class="danger" @click="controlPropzone(task,'delete')">删除</button></div></article></section>
    </section>
    <section v-show="view==='map'" class="map-page">
    <header><div><span class="eyebrow">MAP DATA STUDIO</span><h1>卫星地图下载工作台</h1><p>在地图上框选范围，配置影像参数并批量提交下载任务。</p></div></header>
    <section class="workspace">
      <aside class="panel">
        <div class="panel-title"><b>任务配置</b><span>{{selected}} 个范围</span></div>
        <label>行政区划搜索<div class="searchbox"><input v-model="regionQuery" placeholder="国家、省/州、市、区县" @keyup.enter="searchRegions"><button @click="searchRegions">{{searching?'…':'搜索'}}</button></div></label>
        <div v-if="regionResults.length" class="region-results"><button v-for="region in regionResults" :key="region.id" @click="selectRegion(region)"><b>{{region.name.split(',')[0]}}</b><small>{{region.name}}</small></button></div>
        <div class="grid2"><label>地图数据<select v-model="mapCategory"><option value="imagery">卫星与航拍影像</option><option value="standard">标准地图</option><option value="terrain">地形地图</option><option value="dem">DEM 高程数据</option></select></label><label>数据源<select v-model="form.tile_source"><option v-for="source in availableTileSources" :key="source.id" :value="source.id">{{source.name}}</option></select></label></div>
        <div class="grid2"><label>起始层级<input v-model.number="form.zoom_min" type="number" :min="selectedTileSource?.minZoom" :max="selectedTileSource?.maxZoom"></label><label>结束层级<input v-model.number="form.zoom_max" type="number" :min="selectedTileSource?.minZoom" :max="selectedTileSource?.maxZoom"></label></div><div v-if="selectedTileSource" class="source-zoom-limit">{{selectedTileSource.name}} 支持 Z{{selectedTileSource.minZoom}}–Z{{selectedTileSource.maxZoom}}</div>
        <div class="grid2"><label>并发线程<input v-model.number="form.max_workers" type="number" min="1" max="16"></label><label>GeoTIFF 分块边长<select v-model.number="form.split_size" :disabled="form.output_format!=='tif'"><option :value="1024">1024 px</option><option :value="2048">2048 px</option><option :value="4096">4096 px</option><option :value="8192">8192 px</option></select></label></div>
        <label>导出格式<select v-model="form.output_format" :disabled="form.data_type==='dem'"><option value="png">PNG 图片</option><option value="tif">GeoTIFF · EPSG:3857</option></select></label>
        <div class="hint" v-if="form.data_type==='dem'">地图已切换为分层设色高程图。DEM 以米为单位输出分块 Float32 GeoTIFF，文件在 ZIP 根目录平铺，最高支持 Z15。</div><div class="hint" v-else>任务名称将根据行政区名称或框选坐标自动生成。{{form.output_format==='tif'?'GeoTIFF 按固定像素矩阵分块输出，行政区边界之外填充为黑色。':'PNG 保留原始瓦片，按标准 z/x/y.png 目录保存。'}}</div>
        <div class="actions"><button class="ghost" @click="clearAreas">清空</button><button class="primary" :disabled="!selected||submitting" @click="submit">{{submitting?'提交中…':`创建 ${selected||''} 个任务`}}</button></div>
      </aside>
      <div ref="mapEl" class="map"></div>
    </section>
    <section class="queue"><div class="queue-head"><div><span class="eyebrow">TASK QUEUE</span><h2>下载任务</h2></div><button class="refresh" @click="loadTasks">刷新</button></div>
      <div v-if="!tasks.length" class="empty">暂无任务，在上方地图框选范围开始下载。</div>
      <article v-for="task in tasks" :key="task.id" class="task">
        <div class="task-main"><div class="task-icon"><AiIcon name="map" /></div><div><b>{{task.request.options.output_name}}</b><small>{{dateText(task.created_at)}} · {{tileSourceName(task.request.options.tile_source)}} · Z{{task.request.options.zoom_min??task.request.options.zoom}}–Z{{task.request.options.zoom_max??task.request.options.zoom}} · {{task.id.slice(0,8)}}</small></div></div>
        <div class="progress"><div><span>{{task.message}}</span><strong>{{task.progress}}%</strong></div><div class="track"><i :class="task.status" :style="{width:task.progress+'%'}"></i></div><small v-if="task.error" class="error">{{task.error}}</small></div>
        <span class="badge" :class="task.status">{{statusText(task.status)}}</span>
        <div class="task-actions"><button v-if="task.status==='queued'||task.status==='running'" @click="controlTask(task,'pause')">暂停</button><button v-if="task.status==='paused'" class="resume" @click="controlTask(task,'resume')">继续</button><button v-if="task.status==='failed'||task.status==='cancelled'" class="retry" @click="controlTask(task,'retry')">重试</button><a v-if="task.status==='completed'" class="export" :href="`/api/tasks/${task.id}/export`">导出</a><button class="danger" @click="controlTask(task,'delete')">删除</button></div>
      </article>
    </section>
    </section>
  </main>
</template>
